window.WINES=(window.WINES||[]).concat([{"sheet":"Шампанское","row":3,"year":"NV","title":"Prevoteau-Perrier La Vallee Brut","producer":"Champagne Prevoteau-Perrier","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12.5%","volume":"375 мл","grapes":"Пино Нуар, Шардоне","taste":"Вкус шампанского свежий, чистый, насыщенный, с фруктовыми оттенками (яблоко, цитрусовые), пикантной перечной горчинкой, нюансами тостов и минералов и терпким, бодрящим послевкусием.","aroma":"Аромат шампанского демонстрирует прекрасную фруктовую свежесть, легкие сливочные и дрожжевые нюансы.","color":"Шампанское светло-желтого цвета с темно-золотистыми отблесками.","pairing":"Шампанское прекрасно в качестве аперитива, с закусками, морепродуктами, канапе, тарталетками, изысканными рыбными блюдами, сырами.","description":"Champagne Prevoteau-Perrier, \"La Vallee\" Brut — кюве, типичное для поместья Превото-Перье, производится с момента основания Дома в 1946 году. Это сухое шампанское представляет собой тонкую смесь Шардоне и Пино Нуар и демонстрирует мастерство Дома и изящную, свежую фруктовость. Урожай для его изготовления собирается в Валле де ля Марн (Дамери и окрестные деревни) и Кото-Сюд д’Эперне. В купаж входит виноград трех последовательных винтажей и 20-30% резервных вин. После ферментации, яблочно-молочного брожения и фильтрации вино выдерживается в бутылках минимум 2 года. После дегоржажа шампанское дозревает еще 3-6 месяцев. Брют обладает прекрасными ароматическими качествами, которые делают это кюве идеальным выбором на все случаи жизни и праздничные мероприятия.","producer_description":"Champagne Prevoteau-Perrier — семейная винодельня в Дамери, недалеко от Эперне, основанная в 1946 году. Бренд родился в результате брака между Анри Превото и Алисой Перье. Их сын Патрис значительно расширил семейный виноградник и рынок продаж. Сегодня винодельней руководят Дельфин и Кристоф Будар-Превото вместе со своим сыном Матисом, поддерживая наследие и философию бренда. В настоящее время Дом Шампань Превото-Перье выращивает виноград на 30 гектарах земли в Дамери (включая 22 га собственных участков), в глубине региона Шампань. Обильные запасы винограда обеспечивают Дому постоянство и разнообразие каждого урожая. Семья заботится об окружающей среде и всегда использует традиционные методы обработки почвы, используя вилы, чтобы переворачивать почву и сводить сорняки к минимуму. В июне 2021 года старая практика \"La lutte raisonnée\" была заменена сертификацией HVE \"Высокая экологическая ценность\" (уровень 3). От кропотливого сбора винограда вручную и прессования до дегоржажа и отгрузки, Дельфин и Кристоф уделяют самое пристальное внимание производству и выдержке вина. В зависимости от купажа, каждый винтаж хранится в темных погребах от 2-х до 5 лет, пока не достигнет нужного возраста.","price":13600,"glass_price":"","id":"nv-prevoteau-perrier-la-vallee-brut-champagne-prevoteau-perrier","image":"","price_label":"13 600 ₽","glass_price_label":""},{"sheet":"Шампанское","row":4,"year":"NV","title":"Thierry Fournier Reserve Extra Brut","producer":"Champagne Thierry Fournier","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Пино Менье, Пино Нуар и Шардоне","taste":"Шампанское обладает изящным, тонким вкусом со слегка маслянистой текстурой, освежающей кислотностью, меловыми нюансами и стойким, сбалансированным послевкусием с характерными для выдержанного шампанского ореховыми тонами.","aroma":"Гармоничный аромат шампанского пьянит сложным букетом, сотканным из нот цитрусовых, орехов и сухофруктов","color":"Шампанское демонстрирует яркий светло-золотистый цвет с мелкими и частыми пузырьками.","pairing":"Шампанское прекрасно подойдет в качестве аперитива. Оно сочетается с моллюсками, блюдами из курицы, рыбными деликатесами, фруктами и нежными творожными десертами.","description":"Champagne Thierry Fournier, \"Reserve\" Extra Brut — богатое, яркое шампанское, полученное в результате купажа винограда сортов Пино Менье, Пино Нуар и Шардоне. Виноград произрастает на лозах возрастом около 45 лет, которые, благодаря своей зрелости, дают ягоды с концентрированным и насыщенным вкусом. Сбор урожая осуществляется вручную и поступает со всех виноградников поместья, при этом купаж включает вина нескольких урожаев (доминирующий 2023), что позволяет сохранить сложность вкуса, объединяя отличительные черты качественных терруаров и особенностей каждого винтажа в одной бутылке. Винификация проходит в стальных емкостях, для того чтобы максимально сохранить натуральный, природный освежающий аромат вина. Затем шампанское выдерживается в бутылке на дрожжевом осадке несколько лет перед добавлением дозажного ликера (5,5 г/л), благодаря чему оно обладает насыщенным вкусом с фруктовыми и меловыми оттенками и длительным послевкусием.","producer_description":"Champagne Thierry Fournier — французская семейная компания, история которой началась в 1930 году, когда виноделы с фамилией Фурнье приобрели виноградники в местечке Фестиньи (регион Шампань), расположенном на левом берегу реки Марны. Здесь преобладают глинисто-известковые почвы, идеально подходящие для возделывания классических сортов винограда. В настоящее время плантации хозяйства включают 45 участков с уникальным терруаром, где выращиваются сорта Пино Нуар, Пино Менье и Шардоне. Высококлассное шампанское Thierry Fournier отличается многогранными дегустационными оттенками, балансируя между фруктово-ягодными, минеральными, сливочными и цветочными нотами. Производственный процесс осуществляется с соблюдением строгих экологических стандартов и традиционных технологий, начиная с бережного сбора винограда в удачные годы. Выдержка шампанского на осадке проходит в подвалах винодельни. Шампанское Thierry Fournier — отличный выбор для любителей классики.","price":14200,"glass_price":2400,"id":"nv-thierry-fournier-reserve-extra-brut-champagne-thierry-fournier","image":"","price_label":"14 200 ₽","glass_price_label":"2 400 ₽"},{"sheet":"Шампанское","row":5,"year":"NV","title":"Nathalie Falmet Cuvèe Brut","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Пино Нуар и Шардоне","taste":"Шампанское чарует гармоничным, свежим вкусом с гладкой текстурой, нотами персика, цитрусовых и тостов, утонченной кислинкой и сухим послевкусием.","aroma":"Шампанское демонстрирует освежающий аромат, сотканный из нот персика, яблока, минералов и белых цветов.","color":"Шампанское светло-золотистого цвета с тонким перляжем.","pairing":"Шампанское отлично сочетается с блюдами из рыбы и морепродуктов. Подходит также к десертам и в качестве аперитива.","description":"Nathalie Falmet, Brut, Champagne AOC — роскошное белое шампанское, в производстве которого используется виноград сортов Пино Нуар и Шардоне. Также в купаже присутствует 20% резервных вин. Сбор урожая проводится исключительно вручную в момент оптимальной спелости ягод, на винодельне плоды подвергаются ферментации в стальных резервуарах при контролируемой температуре 16 °С. Вторичная ферментация с последующей выдержкой в бутылках проходит в течение двух лет.","producer_description":"\"Моя философия выращивания винограда, винификации и виноделия, безусловно, самая здоровая с точки зрения уважения к природе, но она также ведет к чистоте и непревзойденному качеству вина. Можно любить вино, просто ценя человека, который его сделал. За каждой этикеткой стоит винодел и важно не отделять их друг от друга\", — Натали Фальме.Изучив химию в университете \"Париж XI\" и получив диплом энолога в Реймсе в 1993 году, Натали Фальме стала владелицей семейного поместья в Кот-де-Бар. Она успешно совмещает оба этих направления, создавай уникальные шампанские вина. На винограднике площадью 3,4 га с глинисто-известковыми почвами Киммериджского периода применяется принцип устойчивого культивирования. Шампанские вина Nathalie Falmet покоряют с первых секунд.","price":14900,"glass_price":"","id":"nv-nathalie-falmet-cuvèe-brut","image":"","price_label":"14 900 ₽","glass_price_label":""},{"sheet":"Шампанское","row":6,"year":"NV","title":"A.Bergere Origine Brut","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Пино Менье, Пино Нуар и Шардоне","taste":"Гармоничный, живой и структурированный. Во вкусе ощущается кремовая текстура, сменяющаяся яркой, освежающей кислотностью и четкой минеральностью. Фруктовые тона (персик, тропические фрукты) уравновешены нюансами мела и миндаля","aroma":"Свежий и элегантный. Доминируют ноты белых фруктов: белого персика, нектарина и груши, а также цитрусовой цедры, белых цветов и легкие хлебные, тостовые нюансы","color":"Светло-золотистый или соломенный с тонким, устойчивым перляжем (игрой пузырьков) и блестящими искрами","pairing":"Идеальный аперитив. Также отлично сочетается с устрицами, морепродуктами, тартарами, легкими закусками и мягкими сырам","description":"Кюве Origine Brut — это визитная карточка дома A. Bergère, созданная из винограда, собранного с собственных виноградников в долине Пти-Морен (Petit Morin) . Купаж, основу которого составляет Шардоне, отражает терруар региона с его меловыми и глинистыми почвами . Вино выдерживается в бутылках в погребах дома в течение нескольких лет, чтобы достичь баланса и сложности, а дозаж составляет 4 г/л (Brut","producer_description":"Семья Bergère владеет виноградниками в Шампани с 1848 года. Бренд Champagne A. Bergère был основан Андре Бержером в 1949 году . Сегодня хозяйство, которым управляет представитель четвертого поколения, энолог Адриен Бержер, владеет 45 гектарами виноградников, разбитых на 139 участков в лучших терруарах Кот-де-Блан, Сезанне и долины Пти-Морен . Особенность дома — раздельная винификация каждого участка и выдержка некоторых вин в дубовых бочках . Погреб и офис продаж дома находятся на знаменитой Авеню де Шампань в Эперне","price":16800,"glass_price":"","id":"nv-a-bergere-origine-brut","image":"","price_label":"16 800 ₽","glass_price_label":""},{"sheet":"Шампанское","row":7,"year":"NV","title":"Henri Giraud Esprit Nature","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Пино Нуар и Шардоне","taste":"Шампанское обладает свежим, обволакивающим, полным вкусом с продолжительным фруктовым послевкусием.","aroma":"Аромат вина наполнен нотами свежих груш, миндаля и инжира, дополненными нюансами цветов апельсина. При легком вращении бокала проявляются насыщенные оттенки меда и свежеиспеченного хлеба.","color":"Шампанское бледно-желтого цвета с оттенком белого золота и красивым перляжем из мелких пузырьков.","pairing":"Шампанское прекрасно в качестве аперитива, отлично сочетается с устрицами, креветками и другими морепродуктами, а также легкими рыбными блюдами.","description":"Henri Giraud, Esprit de Giraud — шампанское с характером, исполненное жизни и остроты. Это открытое, щедрое вино способно сказать о многом своими соблазнительными полунамеками. Как говорят в хозяйстве Жиро, \"делать хорошее вино легко, если Вы уважаете и любите тех, кто будет его пить\" — в этом и заключен \"Esprit\" — \"дух\" компании.","producer_description":"Говоря о компании, Анри Жиро приводит слова своего деда: \"Каким бы ни было вино — молодым, зрелым или выдержанным — оно всегда должно быть хорошим. Это вопрос баланса. Когда мне задают вечный вопрос о характере шампанского Анри Жиро, я спокойно отвечаю: удовольствие, зрелость и терруар\". Эти слова как нельзя лучше отражают философию винодельческого хозяйства.Виноград, достигшей оптимальной зрелости, собирается в лучших терруарах Шампани. Чтобы не повредить ягоды, при сборе урожая соблюдается предельная осторожность. Далее холодному виноградному суслу дают отстояться. На винодельне не используют никакие добавки, применяют лишь обработку сульфитами для защиты и легкую фильтрацию для сохранения большей части субстанции. В завершение, придерживаясь собственного метода хозяйства Giraud, уникального в сфере производства шампанского — вино выдерживают не в бочках, а специальных баках с системой терморегуляции. Процесс длится 12 месяцев, в результате чего получается прекрасное шампанское, которое доставит большое удовольствие всем, кому посчастливится вкусить его.","price":19800,"glass_price":3300,"id":"nv-henri-giraud-esprit-nature","image":"","price_label":"19 800 ₽","glass_price_label":"3 300 ₽"},{"sheet":"Шампанское","row":8,"year":"NV","title":"Geoffroy Purete Premier Cru Brut Nature","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Пино Менье, Пино Нуар и Шардоне","taste":"Шампанское покоряет богатым, очаровательным вкусом с гладкой текстурой, легкими цветочными нюансами и освежающим послевкусием.","aroma":"Шампанское соблазняет чистым, свежим ароматом, сотканным из нот красных яблок, весенних цветов и минералов.","color":"Шампанское привлекательного соломенно-золотистого цвета с утонченным перляжем.","pairing":"Превосходный аперитив, также отлично дополнит блюда из рыбы (такой как окунь или палтус), сыр (козий или пармезан).","description":"\"Purete\" Brut Nature Premier Cru, Champagne AOC — восхитительное шампанское, созданное из купажа трех сортов винограда — Пино Менье, Пино Нуар и Шардоне. Средний возраст виноградных лоз составляет 25 лет. Сбор урожая проводится вручную, на винодельне ягоды подвергаются сортировке с последующим бережным измельчением и прессованием. Ферментация при строго контролируемой температуре проходит в стальных чанах. Малолактическая ферментация не проводится. Часть шампанского выдерживается в дубовых бочках.","producer_description":"Имя Rene Geoffroy известно в винодельческих кругах еще с 17-го века. Это величественный замок, воплощающий лучшие традиции виноделия на протяжении уже многих поколений, а также виноградники, которые расположены недалеко от Эперне, в коммуне Сumieres и имеют классификацию Премьер Крю. Все шампанское, производимое винным домом Рене Жефруа — это нечто изысканное, сочетающее в себе тепло солнца, аромат земли, вкус винограда и лучшие традиции, собранные многими поколениями. В производстве используется только сок, который естественно стекает после первого давления. Философия компании Рене Жефруа — это гармония с природой, возможность раскрыть все свойства земли и окружающей природы в своих винах, при этом сумев сохранить все это богатство будущим поколениям. Это напрямую связано с технологиями производства, выращивания и сбора урожая, а также использования биодинамических принципов и полном отказе от применения каких-либо химикатов. Некоторые виды шампанского, которые производит Рене Жефруа, выдерживаются почти в два раза дольше положенного срока. Ежегодный объем производства составляет немного более 100 тысяч бутылок вина. В 2000 году на трех конкурсах шампанское Дома Жоффруа урожая 1997 года завоевало 7 медалей (3 золотых, 1 серебряная, 3 бронзовых).","price":20900,"glass_price":"","id":"nv-geoffroy-purete-premier-cru-brut-nature","image":"","price_label":"20 900 ₽","glass_price_label":""},{"sheet":"Шампанское","row":9,"year":"NV","title":"Waris-Larmandier Racines de Trois Brut","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12.5%","volume":"750 мл","grapes":"Шардоне,Пино Нуар,Пино Менье","taste":"Элегантный, деликатный и структурированный . Кремовая текстура переходит в приятную освежающую кислотность . Во вкусе доминируют тона лимонного крема, белого персика и фундука. Долгое, сбалансированное послевкусие с ярко выраженным солоноватым минеральным финишем","aroma":"Сложный букет с нотами зеленого яблока, белых цветов, груши, засахаренной апельсиновой цедры и лимона, дополненный оттенками красных фруктов (вишня, слива), поджаренного миндаля, свежей бриоши и прохладной минеральности","color":"Яркий золотисто-желтый с тонким, стойким перляжем","pairing":"Идеальный аперитив. Также отлично сочетается с рыбными блюдами, белым мясом и свежими сырами","description":"Кюве \"Racines de Trois\" (в переводе \"Три корня\") — это визитная карточка хозяйства Waris-Larmandier. Название символизирует \"три корня\": троих братьев, управляющих винодельней, три сорта винограда и три ключевых региона Шампани, откуда происходит виноград. Виноград для этого шампанского собирается с виноградников, возраст которых превышает 50 лет . Винификация проходит с использованием диких дрожжей в стальных чанах и 600-литровых дубовых бочках . Малолактическое брожение происходит спонтанно . Вино выдерживается на осадке в бутылке от 24 до 36 месяцев . Дозаж составляет 4 г/л","producer_description":"Дом Champagne Waris-Larmandier расположен в самом сердце Кот-де-Блан, в Гран Крю деревне Авиз . Хозяйство было основано в 1989 году Мари-Элен и Винсентом Варис . Сегодня винодельней управляют трое детей: Жан-Филипп, Пьер-Луи и Инес, представляющие шестое поколение виноградарей. Виноградник площадью 6.5 гектаров обрабатывается с использованием органических и биодинамических методов (сертификаты Ecocert и Demeter) . Хозяйство практикует травяной покров, ручную обработку почвы и применение органических удобрений. С 2020 года винодельня имеет биодинамический сертификат","price":23500,"glass_price":"","id":"nv-waris-larmandier-racines-de-trois-brut","image":"","price_label":"23 500 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Шампанское","row":10,"year":"NV","title":"Collery Blanc de Blancs Grand Cru Ay Brut","producer":"Champagne Collery","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Шардоне","taste":"Объемная и богатая атака с йодистыми нюансами. Вкус раскрывается теплыми нотами груши Вильямс, переходя в тонизирующий, свежий финиш с яркими цитрусовыми акцентами (апельсин, помело)","aroma":"Сложный и элегантный букет. Вначале раскрываются ноты белых цветов, цукатов (кумкват, манго) и свежей выпечки (сливочное печенье). При \"дыхании\" появляются глубокие оттенки миндаля и поджаренного фундука","color":"Золотистый оттенок с зеленоватыми бликами. Тонкий, изящный перляж, образующий кремовую пен","pairing":"Прекрасен в качестве аперитива. Идеально сочетается с устрицами, моллюсками, икрой, копченым лососем, блюдами из белой рыбы, белого мяса, а также с мягкими и зрелыми сырами","description":"Collery, Blanc de Blancs, Grand Cru Aÿ — это изысканное шампанское, созданное исключительно из винограда сорта Шардоне, выращенного на виноградниках класса Гран Крю в знаменитом регионе Aÿ . Это вино отражает чистоту и элегантность терруара. Сбор урожая проводится вручную, а винификация — с контролем температуры для сохранения свежести аромата . Длительная выдержка на осадке (в течение 5 лет ) придает вину сложность, кремовую текстуру и идеальный баланс . Около 30% ассамбляжа выдерживается в 25-гектолитровых дубовых бочках, а база Шардоне — в бочках из-под Сотерна, что придает вину дополнительные слои ароматов и текстур . Дозаж — 6 г/л . Этот шедевр отмечен множеством наград, включая 97 баллов и статус \"Best in Show\" от Decanter в 2023 году","producer_description":"Champagne Collery — это исторический дом, основанный в 1893 году Жюлем-Анатолем Коллери в городе Aÿ, который с тех пор остается его колыбелью . Дом славится своей приверженностью к качеству и глубокими корнями в терруарах Гран Крю . В разные годы домом управляли выдающиеся личности: Пьер и Женевьева Коллери, которая покорила сердца парижских гурманов, а также Жан Коллери — мэр Aÿ, сенатор и президент природного парка Монтань-де-Рейм, который также стал автором идеи создания розового шампанского Collery методом мацерации . Сегодня дом возрождается под руководством новой команды во главе с Николя и Роменом, которые бережно сочетают наследие прошлого с современными подходами, сохраняя философию \"высокого качества\" (haute qualité) . Виноградники поставщиков тщательно отбираются. Винодельня оснащена как терморегулируемыми стальными чанами, так и дубовыми бочками для точной микрооксигенации. Все вина выдерживаются на осадке не менее 4 лет , а в ассамбляж включается около 20% резервных вин, хранящихся в дубовых бочках . Особое внимание уделяется ликеру дозажа, который создается отдельно для каждого кюве в бочках из-под Сотерна и Бургундии","price":28500,"glass_price":"","id":"nv-collery-blanc-de-blancs-grand-cru-ay-brut-champagne-collery","image":"","price_label":"28 500 ₽","glass_price_label":""},{"sheet":"Шампанское","row":11,"year":"NV","title":"Bereche & Fils Brut Reserve","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12.5%","volume":"750 мл","grapes":"Шардоне, Пино Менье, Пино нуар","taste":"Шампанское обладает чистым, элегантным, насыщенным, сложным и плотным вкусом с оттенками сливы Мирабель, свежеиспеченной груши, сливочного масла, клюквы, белого перца и цветов, яркой кислотностью и стойким, минеральным послевкусием с приятной солоноватостью","aroma":"У шампанского чистый фруктовый аромат с нотками красных фруктов и вишни, желе из айвы, марципана, свежей булочки и специй.","color":"Шампанское светло-золотистого цвета с легкими розовыми отблесками.","pairing":"Шампанское замечательно в качестве аперитива или как сопровождение изысканных блюд из рыбы, морепродуктов, моллюсков.","description":"Bereche & Fils, Brut Reserve, Champagne AOC — изысканное белое шампанское из винограда сортов Шардоне, Пино Нуар и Пино Менье. Виноград выращивается в Шампани на виноградниках Ludes (35%), Elms (30%), Mareuil-le-port (25%) и Trepail (10%). Средний возраст виноградных лоз превышает 40 лет. Виноград собирается вручную по достижении ягодами оптимальной зрелости. Медленное брожение с натуральными дрожжами протекает частично в бочках (60%) и небольших чанах (40%). Доля резервного вина составляет не менее 35%. Вторичная ферментация и выдержка шампанского на осадке в течение 24-36 месяцев осуществляются в бутылке согласно традиционному методу.","producer_description":"Многие критики считают, что шампанский дом Bereche & Fils занял достойное место среди лучших производителей в регионе. Антонио Галлони называет шампанские вина братьев Рафаэля и Винсента Береш, нынешних владельцев Bereche & Fils, \"одними из лучших\", добавляя, что он покупает их вина \"всякий раз, когда я их вижу\". Джон Гилман просто пишет, что Bereche & Fils \"находится на вершине своей деятельности и производит одни из лучших вин во всем регионе Шампань!\" Этот старинный дом был основан в 1847 году. Тем не менее, именно новаторская работа молодых виноделов Рафаэля и Винсента Береш сделала его одним из самых обсуждаемых шампанских домов, сначала среди французских сомелье, кавистов и знатоков, а теперь и их коллег в США. Опираясь на прочный фундамент традиционных методов производства шампанского, которым они научились у своего отца Жан-Пьера, братья стали одними из лучших виноделов региона. Их портфолио включает не только необычайно яркий Brut Reserve, но и несколько особых кюве, блестяще задуманных, чтобы выразить различные аспекты терруара своего происхождения и сорта винограда. Ключом к фантастической сложности шампанских вин Bereche & Fils является количество различных терруаров, составляющих владения поместья. Виноградники Береш можно найти, например, в их родной деревне Лудес на меловых почвах Монтань де Реймс, в Ормсе, Пти Монтань де Реймс и Марей-ле-Порт, в западной долине Валь-де-ла-Марн, а также небольшие участки в Трепай на восточных склонах Монтань де Реймс. В 2012 году братья приобрели первый участок класса Гран Крю, крошечный участок в Мейли и в 2013 году полгектара в Рилли-ла-Монтань к западу от Лудеса. Рафаэль и Винсент неустанно экспериментируют с характером этих совершенно разных терруаров, создавая ряд кюве, ценимых за их оригинальность. За лозами ухаживают десять штатных сотрудников — невероятное количество, учитывая, что владения поместья составляют всего девять гектаров. Это гарантирует, что трудоемкая работа на каждом участке будет выполнена безупречно. Высокое качество на каждом производственном этапе — залог успеха готовой продукции Bereche & Fils!\n\n","price":36500,"glass_price":"","id":"nv-bereche-fils-brut-reserve","image":"","price_label":"36 500 ₽","glass_price_label":""},{"sheet":"Шампанское","row":12,"year":"NV","title":"Roger Coulon «L'Hommee» Premier Cru","producer":"Эрик и Изабель Кулон","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Шардоне, Пино Менье, Пино нуар","taste":"Шампанское имеет элегантный, округлый вкус, сотканный из ноток свежей выпечки, минералов и цитруса. Продолжительное и приятное послевкусие.","aroma":"Шампанское обладает сложным, богатым ароматом с оттенками тостов, дрожжей, яблок и груш, изысканными нотками минералов и цитрусов.","color":"Сверкающий светло-золотистый цвет с тонким перляжем.","pairing":"Шампанское отлично подойдёт как в качестве аперитива, так и в паре с изысканными блюдами. Например, лангустины или равиоли с чёрным трюфелем.","description":"Roger Coulon, \"L'Hommee\" Premier Cru — великолепное в качестве аперитива, флагманское кюве шампанского дома Рожер Кулон, которое отличается своей интенсивностью и длительной выдержкой в ​​погребе. Купаж представлен сортами Пино Нуар, Пино Менье и Шардоне, которые произрастают на виноградниках класса Премье Крю в коммуне Монтань-де-Реймс. Шампанское было названо в честь древнего сельскохозяйственного измерения, эквивалентного поверхности виноградной лозы, который человек мог обработать за один день (около 333 м2). По окончании сбора урожая плоды подвергаются традиционной винификации, проходящей со строгим температурным контролем. Базовое вино выдерживается на осадке в дубовых бочках в течение 7 месяцев. После чего добавляется тиражный ликер и вино попадает в бутылки для вторичного брожения. После 5 лет выдержки получается роскошное шампанское, способное удивить даже искушенного гурмана.","producer_description":"Эрик и Изабель Кулон — представители восьмого поколения семьи Coulon, которые производят восхитительное шампанское из Вриньи и окрестных деревень в северо-западном углу горы Реймс. Дом Roger Coulon был основан в 1806 году. В настоящее время общая площадь виноградников составляет 10 га. Виноградники на 40% засажены сортом Пино Менье, на 30% — сортом Пино Нуар и на 30% — сортом Шардоне. Средний возраст лоз составляет 38 лет, что является редкостью для апелласьона Шампань, где старые лозы и их ограниченное производство часто считаются проклятием, а не благословением. Кроме того, виноградники засажены методом селекции \"масалле\", а не современными клонами. Участки сертифицированы как органические с 2022 года (сертификат Европейской Комиссии: FR-BIO-10.250-0083256.2025.001). Производитель не использует химические добавки, не фильтрует и не осветляет вина, позволяя максимально выразить терруар. Винодельня практикует агролесоводство и поздний сбор урожая для достижения полной физиологической зрелости ягод. Изабель Кулон следующим образом формулирует подход компании к окружающей среде: \"Для нас принципиально важно, чтобы наши вина сохраняли свою идентичность с течением времени, отражали уникальный характер нашего терруара и воплощали особый стиль\". Производство Roger Coulon составляет около 90 000 бутылок в год. Изысканные, роскошные шампанские способны покорить своими органолептическими характеристиками с первых секунд. В 2011 году семья виноделов открыла гостевой дом \"Clos des Terres Soudees\", предлагающий дегустации и экскурсии.","price":37200,"glass_price":"","id":"nv-roger-coulon-l-hommee-premier-cru-erik-i-izabel-kulon","image":"","price_label":"37 200 ₽","glass_price_label":""},{"sheet":"Шампанское","row":13,"year":"2018","title":"Salima & Alain Cordeuil «Altitude 350m» Brut Nature","producer":"Champagne Salima & Alain Cordeuil","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Шардоне","taste":"Вкус полнотелый, богатый, сбалансированный, с бархатистой текстурой, цитрусово-фруктовым профилем, тонкими нюансами миндаля, ванили и трав, живой кислинкой и очаровательным послевкусием.","aroma":"Покоряет роскошным, изысканным, сложным ароматом, сотканным из нот персика, яблока, мандарина, ванили, тостов, цитрусового масла и пряностей.","color":"Шампанское соломенно-желтого цвета с тонкими золотистыми бликами.","pairing":"Шампанское идеально в качестве аперитива, а также пары для изысканных блюд из морепродуктов, рыбы и нежного мяса.","description":"Salima & Alain Cordeuil, \"Altitude 350m\" Brut Nature, Champagne AOC — изысканное натуральное шампанское, для изготовления которого используют виноград сорта Шардоне, собранный вручную с участка в деревеньке Noe-les-Malletts, который расположен на высоте 350 метров над уровнем моря. Возраст виноградных лоз составляет 35 лет. Виноград культивируется исключительно органическими методами на мергелевых почвах. Шампанское производится традиционным методом, согласно которому вторичное брожение и выдержка на осадке протекают в бутылках. Дозировочный ликер не добавляется, о чем свидетельствует надпись Brut Nature.","producer_description":"Champagne Salima & Alain Cordeuil — поместье площадью в 4 га, расположенное в Кот де Бар, в Ноэ-ле-Малле, деревне, где находятся самые высокие склоны Шампани. Именно здесь родилась красивая история Салимы и Алена Кордей. Они самоотверженно любят свою землю и уважают окружающую среду, поэтому сразу решили, что их проект будет органическим. Салима и Ален Кордей начали производство первых шампанских вин в 2011 году с 10 000 бутылок в год, используя исключительно собственный виноград. На винограднике каждое действие осуществляется с полным уважением к почве с целью сохранить ее как можно более живой и здоровой, питая ее только растительными компонентами, поступающими с близлежащей органической фермы. Вспашка проводится при помощи любимого коня. Все шампанские вина Кордей — марочные и исключительно не дозированные. Сульфиты используются в очень малых дозах, только при необходимости. С 2015 года все виноградники Champagne Salima & Alain Cordeuil сертифицированы как органические.","price":39000,"glass_price":"","id":"2018-salima-alain-cordeuil-altitude-350m-brut-nature-champagne-salima-alain-cordeuil","image":"","price_label":"39 000 ₽","glass_price_label":""},{"sheet":"Шампанское","row":14,"year":"2009","title":"Andre Baeufort Polisy Blanc de Noirs","producer":"Champagne André Beaufort","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Пино нуар","taste":"Объемный, насыщенный, с упругой текстурой и сложной структурой. Вкус отличается прекрасным балансом кислотности, который сохраняет свежесть. Терпкие тона лимонного сорбета и яблочного пирога подчеркнуты тонкой минеральностью. Послевкусие глубокое, долгое и пикантное","aroma":"Сложный, многогранный букет. Доминируют ноты спелых желтых фруктов — груши, айвы, яблочного пюре, а также цитрусовых. Со временем раскрываются оттенки поджаренных тостов, меда, ванили, орехов и сухих луговых трав. Некоторые источники отмечают ноты карамели, лайма и можжевельника","color":"Золотисто-желтый с деликатным, мелким и утонченным перляжем","pairing":"Идеальный аперитив. Отлично сочетается с изысканными деликатесами (например, фуа-гра), морепродуктами, блюдами из белого мяса (террины), рыбой, выдержанными сырами, а также пикантными закусками, такими как волован","description":"Andre Beaufort, \"Polisy\" Millesime Blanc de Noirs Brut — это винтажное шампанское, созданное исключительно из винограда сорта Пино Нуар, выращенного на органических виноградниках Дома в коммуне Полизи . Виноградник расположен в субрегионе Кот-де-Бар на киммериджских глинистых почвах, что придает вину живой характер и тонкую минеральность. После сбора урожая виноград бережно прессуется, сусло отстаивается не менее 12 часов, после чего следует первичная ферментация с использованием натуральных дрожжей. По завершении яблочно-молочного брожения вино выдерживается в старых дубовых бочках в течение 10 месяцев . Вторичная ферментация проходит в бутылке, после чего следует длительная выдержка на тонком осадке. Дозаж составляет 0 г/л (Brut Nature / Extra Brut)","producer_description":"Champagne André Beaufort — уникальное семейное хозяйство, расположенное в Кот-де-Бар. Жак Бофор взял на себя управление имением в 1969 году . С 1971 года хозяйство стало пионером агробиологии в регионе, а с 1994 года имеет органический сертификат (100% площади сертифицировано, урожай 1997 года стал первым официально органическим). Особенность дома — применение альтернативных методов защиты лоз: с 1974 года используются эфирные масла для борьбы с грибковыми заболеваниями, а с 1980 года — гомеопатические препараты . Это позволяет минимизировать использование меди и серы. Все вина производятся исключительно из собственного винограда, а выдержка шампанского значительно дольше общепринятой в регионе, что придает винам неповторимый, выразительный характер .","price":49800,"glass_price":"","id":"2009-andre-baeufort-polisy-blanc-de-noirs-49800-champagne-andré-beaufort","image":"","price_label":"49 800 ₽","glass_price_label":""},{"sheet":"Шампанское","row":15,"year":"2015","title":"Louis Roederer Cristal Brut","producer":"Champagne Louis Roederer","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12.5%","volume":"750 мл","grapes":"Пино нуар, шардоне","taste":"Прекрасно структурированное, округлое, с оттенками сдобной выпечки и ванили . Во вкусе также доминируют тона засахаренных цитрусов, йодистых специй и белой фруктовой мякоти . Текстура шелковистая, почти маслянистая, затем становится более упругой, а свежесть нарастает, становясь чистой и точной . Послевкусие элегантное, продолжительное, с легкой горчинкой и солоноватыми, сливочными нотами","aroma":"Насыщенный и элегантный букет с доминантой белых цветов, цитрусовых (лимон, апельсин), ананаса и белой смородины . Также ощущаются ноты желтых фруктов — белого персика и мирабели . С развитием в бокале появляются медовые нотки, тона жареных орехов (фундук, миндаль), холодный дым и бриош","color":"Светло-соломенный цвет с благородным янтарным блеском и тонким, изящным перляжем . Интенсивный желтый с яркими блестками и ультра-тонкой, динамичной игрой пузырьков","pairing":"Идеальным сопровождением этому роскошному шампанскому станут гребешки, черная икра, лосось, лангусты и устрицы . Также отлично подходит в качестве аперитива и к блюдам высокой кухни","description":"Louis Roederer, Cristal Brut 2015 — это легендарное шампанское, созданное в 1876 году для российского императора Александра II. Винтаж 2015 года стал исключительным: он был создан из винограда со всех 45 участков дома, предназначенных для Cristal, что не происходило с 2002 года. Сбор урожая проходил с 7 по 20 сентября 2015 года. Виноградники расположены в коммунах Гран Крю областей Монтань-де-Реймс, долина Марны и Кот-де-Блан, среди которых ключевые крю: Верзене, Верзи, Бомон-сюр-Вель, Ай, Авиз, Ле-Мениль-сюр-Оже и Краман. Почвы — преимущественно известняковые, что придает вину характерную минеральность и элегантность. Сбор винограда осуществляется вручную, для производства используется сусло только первого отжима — \"кюве\". Около 25% вин выдерживаются в дубовых бочках с регулярным батоннажем, однако малолактическая ферментация не проводится, что позволяет сохранить яркую кислотность и свежесть. Дозаж составляет 7 г/л. Выдержка проходит в бутылках на осадке в течение 5-6 лет, а после дегоржажа вино дозревает еще 8 месяцев. Благодаря исключительной структуре и балансу, потенциал хранения Cristal 2015 оценивается в 15-30 лет, что позволяет этому шампанскому раскрываться и развиваться в бутылке на протяжении десятилетий.","producer_description":"Champagne Louis Roederer — один из старейших и наиболее уважаемых независимых домов Шампани, основанный в 1776 году. С 1833 года он находится в собственности семьи Родерер, что является редкостью для крупных шампанских домов и гарантирует сохранение стиля и философии на протяжении почти двух веков. Сегодня дом владеет 214 гектарами виноградников, расположенными в самых престижных коммунах Шампани. История Cristal начинается в 1876 году, когда Louis Roederer получает специальный заказ от российского императора Александра II. Вино для царя разливают в бутылки из хрусталя, украшенные гербом Российской империи, а кюве называют Cristal (хрусталь, фр.). Двуглавый орел остается неизменным символом этого вина по сей день, напоминая о его царственном происхождении. Впервые в 2012 году для престижного кюве Cristal все 100% винограда было собрано с участков, которые возделывают по биодинамическим принципам, что подтверждает стремление дома к высочайшему качеству и бережному отношению к терруару.","price":125000,"glass_price":"","id":"2015-louis-roederer-cristal-brut-champagne-louis-roederer","image":"","price_label":"125 000 ₽","glass_price_label":""},{"sheet":"Шампанское","row":17,"year":"NV","title":"Paul Bara Brut Reserve Bouzy Grand Cru","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12.5%","volume":"750 мл","grapes":"Пино нуар, шардоне","taste":"Шампанское демонстрирует освежающий, богатый вкус с нотами цитрусовых фруктов и красных ягод, с пикантной кислинкой и элегантным послевкусием.","aroma":"Шампанское покоряет свежим, изысканным ароматом с нотами лимона, смородины, апельсинового творога, душистых трав и лепестков роз.","color":"Шампанское привлекательного светло-золотистого цвета с утонченным перляжем.","pairing":"Шампанское — превосходный аперитив, также отлично дополнит блюда из рыбы (такой как окунь или палтус), сыр (козий или пармезан).","description":"Paul Bara, Brut Reserve Grand Cru — элегантное шампанское, созданное из купажа двух сортов винограда — Пино Нуар и Шардоне, которые произрастают на виноградниках дома Поль Бара на известковых почвах. Средний возраст виноградных лоз составляет 35 лет. После сбора урожая, который проводится вручную, ягоды подвергаются ферментации при строго контролируемой температуре в цистернах из нержавеющей стали. Вторичная ферментация проходит в бутылке. Выдерживается шампанское минимум 3 года в бутылках в погребах винодельни.","producer_description":"Основанное в 1833 году в городке Bouzy, хозяйство Paul Bara на протяжении более 170 лет находится под управлением семьи Бара. Главной целью компании является приверженность семейных ценностей и традиционных методов виноделия. В течение многих десятилетий продукция дома Бара сохраняет свой классический характер, в то время как оборудование постоянно модернизируется и совершенствуется. Paul Bara является членом элитного клуба \"Club Trésors de Champagne\". Многолетний опыт, уважение традиций и бережное отношение к терруару — это отличительные черты бренда. На сегодняшний день шампанские вина Paul Bara покоряют сердца многих ценителей по всему миру.","price":13000,"glass_price":"","id":"nv-paul-bara-brut-reserve-bouzy-grand-cru","image":"","price_label":"13 000 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Шампанское","row":18,"year":"NV","title":"Palmer & Co Rose Solera Brut","producer":"","category":"Шампанское","region":"Шампань, Франция","country":"Шампань","abv":"12%","volume":"750 мл","grapes":"Шардоне, пино нуар, пино менье","taste":"Вкус округлый, элегантный, щедрый, чистый, с креповой текстурой, нотами красных ягод, специй, сушеной цитрусовой цедры и свежеиспеченного хлеба, яркой, живой кислинкой и долгим, интригующим послевкусием.","aroma":"Богатый, роскошный, очаровательный аромат раскрывается в бокале оттенками имбирного пряника, датского вина, пряного яблока, дробленого камня и розового грейпфрута. Через время в букете проявляются штрихи трюфеля и розовой соли.","color":"Обладает красивым розовым цветом с утонченным перляжем.","pairing":"Рекомендуется в качестве аперитива, хорошо сочетается с блюдами из рыбы и морепродуктов.","description":"Palmer & Co, Rose Solera, Champagne AOC — очаровательное розовое шампанское, в производстве которого используется купаж трех сортов винограда. Ягоды произрастают на участках класса Премье Крю и Гран Крю в регионе Монтань-де-Реймс. Сбор урожая проводится исключительно вручную в момент оптимальной спелости ягод, на винодельне плоды подвергаются бережному прессованию с последующей ферментацией в терморегулируемых чанах. В купаж добавляется 30-35% резервных вин и 7-8% красного вина из сорта Пино Нуар, выдержанного методом солера. Вторичная ферментация проводится в бутылке. Выдерживается шампанское на осадке на протяжении 30 месяцев. Наиболее полно шампанское раскроет свои органолептические характеристики при температуре 8-10 °С.","producer_description":"Компания Palmer & Co была основана более семидесяти лет назад, в 1947 году, семью семьями виноделов с ценными виноградниками Premier Cru и Grand Cru в регионе Монтань-де-Реймс в Шампани. Виноделов объединило стремление к совершенству и видение создания шампанского дома, известного своей страстью к гармонии, балансу и стремлению к идеалу. Сегодня эти качества по-прежнему определяют стиль Champagne Palmer & Co. Производство шампанских вин с уважением к окружающей среде и сохранением целостности винограда — это ответственность и обязанность, к которым в Palmer & Co относятся со всей серьезностью. Специалисты постоянно находятся начеку и оказывают поддержку виноделам в выборе методов, обеспечивающих максимальное уважение к людям и окружающей среде, участвующим в процессе выращивания винограда.","price":15800,"glass_price":"","id":"nv-palmer-co-rose-solera-brut","image":"","price_label":"15 800 ₽","glass_price_label":""},{"sheet":"Игристое","row":3,"year":"NV","title":"Prosecco Universo di","producer":"Corvezzo","category":"Игристое вино, Просекко DOC, Экстра Драй","region":"Италия, Венето (на основе вин из зон Valdobbiadene DOCG и Asolo DOCG)","country":"Италия","abv":"11%","volume":"750 мл","grapes":"Глера","taste":"Сухое, свежее, с живой кислотностью и деликатной текстурой. Во вкусе преобладают тона белых фруктов, легкая минеральность и элегантное, сочное послевкусие . Содержание сахара — 6 г/л","aroma":"Свежий и фруктовый букет с доминантой желтого яблока, ананаса и цитрусовых (лайм), дополненный цветочными нюансами ромашки","color":"Соломенно-желтый с серебристым отливом, тонкий и стойкий перляж","pairing":"Универсальное гастрономичное вино. Прекрасно в качестве аперитива, а также к морепродуктам, легким закускам, блюдам из рыбы и пасте","description":"Universo di Corvezzo — эксклюзивное просекко, созданное в результате коллаборации ресторанов «Кофемания», виноторговой компании Vinoterra и семейной винодельни Corvezzo . В основе вина лежат базовые вина из двух лучших зон Prosecco DOCG — Valdobbiadene (отвечает за фруктовость и легкость) и Asolo (придает строгость, минеральность и структуру). Поскольку регламент Prosecco DOCG не допускает ассамбляжа вин из двух зон DOCG, финальное кюве выпущено под классификацией Prosecco DOC . Вино отличается низким содержанием сахара (6 г/л), что делает его особенно гастрономичным . Дизайн этикетки, разработанный художницей Асей Вейгерт, символически отождествляет содержимое бокала со вселенной (universo в переводе с итальянского)","producer_description":"Семейная винодельня Corvezzo, основанная Джованни Корвеццо, расположена в регионе Венето и известна приверженностью принципам органического виноделия и устойчивого развития . Землю на виноградниках обрабатывают без использования химических удобрений и пестицидов, электричество вырабатывают солнечные батареи, а вместо пластиковых пробок используют корковые . Вся продукция имеет органическую сертификацию","price":1100,"glass_price":1100,"id":"nv-prosecco-universo-di-corvezzo","image":"","price_label":"1 100 ₽","glass_price_label":"1 100 ₽"},{"sheet":"Игристое","row":4,"year":"2021","title":"Black Prince Blanc de Noirs Methode Classique","producer":"Золотая Балка","category":"Игристое вино, белое экстра-брют","region":"Россия, Крым, Севастополь","country":"Россия","abv":"12.5%","volume":"750 мл","grapes":"Пино нуар","taste":"Сочное, минеральное, с богатой и многослойной текстурой. Вкус глубокий, стройный и сбалансированный, с выраженной кислотностью и долгим послевкусием. Благодаря экстра-брюту (3 г/л сахара) вино обладает яркой свежестью и гастрономичностью.","aroma":"Букет раскрывается нотами спелых фруктов — персика и сливы, которые переплетаются с тонами бисквита и легкими сливочными нюансами. Также присутствуют оттенки лесных ягод и земляники, характерные для Пино Нуар.","color":"Светло-золотистый, с тонким и стойким перляжем","pairing":"Идеальный аперитив. Прекрасно сочетается с чёрной икрой, моллюсками под сливочным соусом, ризотто с лисичками, соте из кролика, сырным суфле или сырами типа шевр. Также отлично подходит к лососю с драниками, шведскому тосту с лососем, хумусу с запечённым томатом, цезарю с глазуньей и курице с рисом и зелёным карри.","description":"Black Prince Blanc de Noirs Prestige Cuvée — это винтажное игристое вино, созданное классическим шампанским методом из красного сорта Пино Нуар, но без контакта с кожицей, что делает его белым (Blanc de Noirs). Вино выдерживается на дрожжевом осадке в течение 3 лет, что придает ему характерные бисквитные и хлебные тона, а также глубокий, сбалансированный вкус. Это одно из лучших игристых вин Золотой Балки, производимое только в исключительные годы. Название и оформление этикетки отсылают к легендарному британскому фрегату «Принц» (прозванному «Черным принцем»), затонувшему в Балаклавской бухте в 1854 году с сокровищами на борту. В ресторанах вино представлено эксклюзивно в «Кофемании».","producer_description":"Винодельческое хозяйство «Золотая Балка» расположено в Севастополе, в Балаклавской долине Крыма. Оно было основано в 1889 году и является одним из старейших и крупнейших производителей игристых вин в России. Виноградники находятся на уникальных терруарах с глинисто-сланцевыми и известняковыми почвами, близость к морю создает особый микроклимат. Сегодня «Золотая Балка» сочетает многовековые традиции с современными технологиями, включая использование классического шампанского метода (метод шампанизации) для создания премиальных игристых вин, таких как Black Prince. Хозяйство также известно своей приверженностью к качеству и сохранению автохтонных сортов.","price":7200,"glass_price":1250,"id":"2021-black-prince-blanc-de-noirs-methode-classique-zolotaya-balka","image":"","price_label":"7 200 ₽","glass_price_label":"1 250 ₽"},{"sheet":"Игристое","row":5,"year":"NV","title":"Cremant de Bourgogne Brut Rose Andre Delorme","producer":"","category":"Игристое вино, розовое брют","region":"Франция, Бургундия","country":"Франция","abv":"12%","volume":"750 мл","grapes":"Алиготе, Шардоне, Пино Нуар, Гаме","taste":"Освежающий, с обволакивающими сливочными оттенками и сладко-кислой ноткой барбариса на финише. Благодаря выдержке на осадке в течение 12–15 месяцев вино приобретает нежную кремовую текстуру и сбалансированную кислотность.","aroma":"Букет соткан из красных ягод — малины, вишни и особенно клубники, дополненных нотками апельсиновой цедры и цветов.","color":"Ослепительный розовый, с тонким и стойким перляжем.","pairing":"Универсальный гастрономичный партнер. Прекрасно в качестве аперитива, а также к легким закускам, блюдам из рыбы и морепродуктов, красной рыбе, мясным тартарам и даже красному мясу. Особенно хорошо сочетается с лососем с драниками.","description":"Andre Delorme, Cremant de Bourgogne Brut Rosé — это игристое вино, созданное традиционным методом (метод шампанизации) за пределами Шампани, что позволяет называть его «младшим братом» шампанского. Купаж из четырех сортов винограда, включая красные Пино Нуар и Гаме, придает вину яркий ягодный характер и насыщенный розовый цвет. Выдержка на дрожжевом осадке в течение 12–15 месяцев обогащает вкус сливочными и бисквитными нюансами. Это элегантное и утонченное вино отражает терруар Бургундии и мастерство виноделов, сохраняя при этом доступность и демократичность, характерные для креманов.","producer_description":"История дома Andre Delorme началась в 1942 году, когда Андре Делорм, получив ранение на фронте Второй мировой войны, вернулся домой и основал собственное винодельческое хозяйство. Несмотря на тяжелые времена, он начал создавать вина, которые быстро завоевали признание в ресторанной индустрии. После войны к нему присоединился сын, и вместе они расширили виноградники и укрепили репутацию бренда. В 2005 году поместье приобрел Эрик Пиффо, владелец Veuve Ambal, который продолжил традиции и модернизировал производство. Сегодня продукция Andre Delorme пользуется успехом во многих странах, подтвержденным многочисленными наградами и медалями. Дом известен своими креманами, которые сочетают бургундское наследие с современным качеством.","price":8900,"glass_price":1500,"id":"nv-cremant-de-bourgogne-brut-rose-andre-delorme","image":"","price_label":"8 900 ₽","glass_price_label":"1 500 ₽"},{"sheet":"Игристое","row":6,"year":"NV","title":"Corpinnat Plot Twist Brut","producer":"Nadal","category":"Игристое вино, белое брют","region":"Испания, Каталония (Пенедес)","country":"Испания","abv":"12%","volume":"750 мл","grapes":"Макабео, Парельяда, Чарелло, Мальвазия де Сиджес","taste":"Сухой, свежий, с кремовой текстурой и мелкой, тающей во рту игрой пузырьков. Вкус отличается сбалансированной фруктовой кислотностью и гармоничным, продолжительным послевкусием с минеральными нюансами . Содержание сахара: 5 г/л .","aroma":"Фруктовый букет с доминантой косточковых фруктов (персик, абрикос), груши и яблок, дополненный легкими оттенками коньяка, миндаля и свежей выпечки","color":"Бледно-желтый, с тонким и изящным перляжем","pairing":"Универсальный аперитив. Отлично сочетается с канапе, тапас с креветками, закусками, легкими блюдами из рыбы и морепродуктов . Температура подачи: 6–9 °C.","description":"Nadal Plot Twist Brut — это игристое вино категории Corpinnat (престижная альтернатива кава, гарантирующая высокое качество и происхождение из лучших виноградников Каталонии) . Вино создано традиционным методом шампанизации с длительной выдержкой на осадке . Название Plot Twist (в переводе — «сюжетный поворот») отражает идею будущего четвертого поколения винодельни Мирейи Надаль: использование классических сортов с тонким добавлением редкой Мальвазии де Сиджес, которая придает вину уникальный характер и свежесть .","producer_description":"Семейная винодельня Caves Nadal основана в 1943 году Энриком Надалем в Эль-Пла-дель-Пенедес и с тех пор остается в собственности семьи . Хозяйство расположено в самом сердце Пенедеса (Каталония), где лозы растут на известково-глинистых почвах . Сегодня винодельня специализируется на производстве вин категории Corpinnat, уделяя особое внимание органическому виноградарству, ручному сбору урожая и уважению к терруару . Вина Nadal отмечены критиками за чистоту фруктовых нот и точность исполнения .","price":11500,"glass_price":"","id":"nv-corpinnat-plot-twist-brut-nadal","image":"","price_label":"11 500 ₽","glass_price_label":""},{"sheet":"Безалкогольное","row":3,"year":"NV","title":"Blanc de Blancs","producer":"Oddbird","category":"Игристое белое сухое","region":"Франция, Лангедок-Руссильон","country":"Франция","abv":"0%","volume":"200 / 750 мл","grapes":"Шардоне","taste":"Вкус игристого вина мягкий, чистый, с цитрусовыми акцентами и пикантной кислинкой в интригующем послевкусии.","aroma":"Игристое вино привлекает освежающим, гармоничным ароматом, сотканным из нот яблока, лайма, лимонной цедры, миндаля и меда.","color":"Игристое вино соломенно-золотистого цвета.","pairing":"Игристое вино идеально в качестве аперитива, а также в сочетании с легкими закусками, сырами и фруктами.","description":"Oddbird Blanc de Blancs No Alcohol — безалкогольное игристое белое на основе Chardonnay из Лангедока. Технологическая логика строится так: сначала виноград проходит полноценную винную ферментацию в стальных резервуарах при контролируемой температуре, благодаря чему формируются винные кислоты, ароматические соединения и структура. Только после этого алкоголь удаляют вакуумной дистилляцией при низкой температуре около 28 °C. Низкая температура нужна для того, чтобы минимально повредить летучую ароматику. После деалкоголизации основа выдерживается около 12 месяцев, а затем создаётся игристый стиль.\n\nВ бокале это не сладкий газированный сок: профиль строится на яблоке, лайме, лимонной цедре, миндале, лёгких медовых и хлебных нюансах; во вкусе важны свежесть, цитрусовая кислотность и аккуратная пикантность. Ключевая особенность: «сначала вино — потом удаление алкоголя». Хорошо работает как аперитив и с лёгкими закусками, морепродуктами, мягкими сырами и блюдами, где нужна кислотность, но не алкоголь.","producer_description":"Oddbird — шведский проект, основанный Моа Гюрбюзером в 2013 году. До работы с напитками она много лет была социальным работником и семейным терапевтом; идея бренда выросла из желания изменить отношение общества к алкоголю и сделать отказ от него полноценным выбором, а не компромиссом. Компания позиционирует себя как производитель качественных деалкоголизированных вин, а не сладких «имитаций».\n\nOddbird работает с виноградом и винодельческими партнёрами в традиционных европейских регионах, прежде всего во Франции и Италии. Главный принцип — сначала получить полноценное вино, дать ему время на созревание, а затем бережно удалить алкоголь. Компания сотрудничает с профессионалами ресторанной индустрии и сомелье, поэтому продукты проектируются с расчётом на подачу за столом и гастрономические сочетания. Oddbird — специализированный alcohol-free wine brand, чья идентичность строится не вокруг исторического château, а вокруг технологии и культуры качественной деалкоголизации.","price":6500,"glass_price":"","id":"nv-blanc-de-blancs-oddbird","image":"","price_label":"6 500 ₽","glass_price_label":""},{"sheet":"Безалкогольное","row":4,"year":"2024","title":"Le Naturel Zero Zero Blanco Vintae","producer":"Le Naturel","category":"Безалкогольное белое тихое","region":"Испания, Navarra, Valle de Yerri","country":"Испания","abv":"0.0%","volume":"750 мл","grapes":"Garnacha Blanca, Viura","taste":"Мягкий и обволакивающий вход с лёгкой сладковатой фруктовостью, хорошей кислотностью, освежающими цитрусовыми нотами и гармоничным продолжительным финишем.","aroma":"Косточковые и семечковые фрукты, белые цветы, лёгкие медовые оттенки.","color":"Соломенно-жёлтый средней интенсивности с лёгкими золотистыми бликами; чистый и яркий.","pairing":"Аперитив, салаты, рыба, морепродукты, лёгкие овощные блюда.","description":"Le Naturel Zero Zero Blanco 2024 сначала производят как полноценное белое вино, а уже после завершения брожения удаляют алкоголь. Виноград Garnacha Blanca и Viura поступает из Navarra, из Valle de Yerri. Проект работает с органически возделываемыми виноградниками; прохладные глинисто-известковые почвы помогают сохранять кислотность и свежесть. Урожай собирают вручную во второй половине сентября. После мягкого прессования сусло ферментирует на природных дрожжах при температуре не выше 16 °C — низкая температура нужна, чтобы сохранить белые цветы, косточковые фрукты и цитрусовые тона. После обычной алкогольной ферментации готовое вино подвергают деликатной холодной деалкоголизации. Zero Zero — именно деалкоголизированное вино, а не виноградный напиток: в нём сохраняются структура, кислотность и ароматические соединения, сформировавшиеся во время ферментации. Стиль лёгкий, свежий и фруктовый, без тяжести, с мягкой текстурой и чистым цитрусовым финишем.\n\nПроизводственная схема состоит из полноценной винификации с последующим удалением алкоголя. Именно поэтому профиль ближе к настоящему белому вину, чем к соку.","producer_description":"Le Naturel — винная линия группы Vintae, связанная с Aroa Bodegas в Наварре. Проект строится вокруг органического виноградарства, минимального вмешательства и максимально естественного выражения винограда. Вина Le Naturel узнаваемы по простому визуальному стилю и идее «меньше технологического макияжа»: чистое сырьё, бережная винификация и отказ от ненужных операций там, где они не требуются. Безалкогольная серия Zero Zero продолжает ту же логику, но решает отдельную технологическую задачу — сохранить органолептику полноценного вина после удаления алкоголя.\n\nVintae — не одно классическое поместье, а испанская винная группа с проектами в разных регионах; Le Naturel — один из её терруарных проектов в Navarra. Идентичность производителя строится вокруг философии проекта и его происхождения, а не модели традиционного château или domaine.","price":3900,"glass_price":"","id":"2024-le-naturel-zero-zero-blanco-vintae-le-naturel","image":"","price_label":"3 900 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Безалкогольное","row":5,"year":"2024","title":"Red Convivi","producer":"Convivi","category":"Безалкогольное красное тихое","region":"Италия, Friuli-Venezia Giulia","country":"Италия","abv":"0,5%","volume":"750 мл","grapes":"100% Merlot","taste":"Сочное, фруктовое и среднетелое; вишня, слива и тёмные ягоды, мягкие танины, свежая кислотность и лёгкая пряность в финише.","aroma":"Малина, вишня, слива, ежевика; лёгкие пряные и дубовые оттенки.","color":"Рубиновый с фиолетовым оттенком.","pairing":"Мясные закуски, хамон и чоризо, запечённые овощи и грибы, рататуй, мясная пицца, лазанья; 16–18 °C.","description":"Convivi Red 2024 — безалкогольное красное из 100% Merlot, произведённое во Friuli-Venezia Giulia. Виноградники расположены на каменистых, галечных и аллювиальных почвах с хорошим дренажом. Сначала виноград проходит классическую винификацию красного вина: алкогольная ферментация идёт в ёмкостях из нержавеющей стали, то есть ароматическая и вкусовая структура формируется в результате настоящего брожения. Затем вино выдерживают около 6 месяцев в дубовых бочках — это смягчает танины и добавляет лёгкие пряные оттенки. Только после выдержки алкоголь удаляют методом мягкой мембранной фильтрации, обратного осмоса. Такая схема помогает сохранить больше исходных ароматов, чем при грубом нагреве.\n\nГотовое вино имеет 0,5% об.: рубиновый цвет с фиолетовым оттенком, ароматы малины, вишни, сливы и ежевики, мягкие танины, свежую кислотность и фруктово-пряный финиш. Показательно, что у Convivi сохраняется логика настоящего красного вина — ферментация, танинная структура и влияние дубовой выдержки — несмотря на последующую деалкоголизацию.","producer_description":"Convivi — итальянская линия безалкогольных вин, созданная вокруг принципа «сначала вино — затем деалкоголизация». Для Red 2024 профильный источник подтверждает происхождение Friuli-Venezia Giulia, 100% Merlot, крепость 0,5%, выдержку в дубе и обратный осмос. В ряде торговых источников фигурирует Lea Winery как производственная площадка, тогда как бренд указывается как Convivi. Подробная история хозяйства, даты основания и площади собственных виноградников в открытых первичных источниках раскрыты ограниченно.\n\nКонцепция проекта основана на полноценной ферментации вина с последующим бережным удалением алкоголя при сохранении винной структуры и характера подачи. Это принципиально отличает продукт от ароматизированных безалкогольных напитков. Дополнительные сведения о владельцах, площадях и конкретной винодельческой площадке в открытых первичных источниках пока ограничены.","price":4900,"glass_price":"","id":"2024-red-convivi-convivi","image":"","price_label":"4 900 ₽","glass_price_label":""},{"sheet":"Розовое","row":3,"year":"2022","title":"Touraine Rosé François Chidaine","producer":"Domaine François Chidaine","category":"Розовое сухое, тихое; AOC Touraine","region":"Франция, Долина Луары, Touraine (долина Шер)","country":"Франция","abv":"13%","volume":"750 мл","grapes":"Grolleau, Pinot Noir, Gamay. Wine.com для 2022 указывает равные доли; сайт хозяйства подтверждает состав без процентов.","taste":"Сухое, сочное и живое; хорошая кислотность, аппетитная ягодная фруктовость, мелово-минеральная текстура и освежающий финиш.","aroma":"Малина, клубника, крыжовник, тонкие цветочные и минеральные оттенки.","color":"Лососево-розовый, чистый и яркий.","pairing":"Аперитив, летние салаты, тарт с овощами, гриль, птица, charcuterie, блюда с красными ягодами.","description":"Touraine Rosé 2022 Франсуа Шидена — сухое розе из Grolleau, Pinot Noir и Gamay. Виноград происходит из Touraine, с участков хозяйства в долине Шер; хозяйство работает без синтетической химии и следует биодинамическому подходу. Для розе ягоды прессуют напрямую, поэтому контакт с кожицей короткий: отсюда светлый лососевый оттенок, нежные танины и акцент на свежести. После прессования сусло холодно отстаивают, затем ферментируют на природных дрожжах в нержавеющей стали при низкой температуре, сохраняя красноягодную и цветочную ароматику. Вино остаётся на осадке до розлива, что добавляет текстуры без потери лёгкости.\n\nВ источниках по винтажу 2022 встречается указание на равные доли трёх сортов, тогда как сайт хозяйства подтверждает состав без процентов; точные доли поэтому остаются неподтверждёнными. Главная стилистическая идея: это не сладковатое «пляжное» розе, а сухое, минеральное, гастрономичное Loire rosé с сочной кислотностью, ягодным фруктом и меловой свежестью. Сочетание прямого прессования, природных дрожжей, стали и работы с осадком объясняет свежесть вина при сохранении текстуры.","producer_description":"François Chidaine — одно из ключевых имён Montlouis-sur-Loire и современной Луары. Франсуа начинал в семейном хозяйстве, а собственный домен развивал с акцентом на Chenin Blanc и терруары вокруг Montlouis и Vouvray; параллельно хозяйство работает и с участками Touraine в долине Шер. Виноградники возделываются органически и биодинамически: важны живые почвы, ручная работа и минимальное вмешательство в погребе. Ферментации обычно проходят на природных дрожжах, а техника выбирается так, чтобы не скрывать происхождение вина.\n\nСтиль Chidaine ценят за сочетание зрелости плода, высокой естественной кислотности и ясной минеральности. Имя François Chidaine чаще ассоциируется с великими Chenin из Montlouis/Vouvray, но Touraine Rosé показывает более лёгкую сторону хозяйства и ту же философию точного, чистого терруарного вина.","price":7200,"glass_price":1200,"id":"2022-touraine-rosé-françois-chidaine-domaine-françois-chidaine","image":"","price_label":"7 200 ₽","glass_price_label":"1 200 ₽"},{"sheet":"Белое","row":3,"year":"2022","title":"Vermentino","producer":"Igor Larionov / партнёрская винодельня","category":"Белое сухое, тихое","region":"Австралия, South Australia, McLaren Vale","country":"Австралия","abv":"11,5% — подтвердить по вашей бутылке","volume":"750 мл","grapes":"Vermentino","taste":"Вкусовой профиль конкретного винтажа 2022 не заполнен из-за отсутствия подтверждённого винтажного техлиста.","aroma":"Требует сверки по техлисту именно 2022.","color":"Требует сверки по бутылке/техлисту.","pairing":"После сверки винтажа: морепродукты, белая рыба, салаты и лёгкие закуски обычно являются базовыми сочетаниями для сухого Vermentino.","description":"Vermentino 2022 под брендом Igor Larionov — вино, по которому открытые источники дают ограниченный объём технической информации. Импортные записи подтверждают винтаж 2022, сорт Vermentino, происхождение South Australia и крепость около 11,5%; привязка именно к McLaren Vale и детали винификации в открытых источниках остаются не полностью подтверждёнными. Подтверждённые сведения о технологии именно этого винтажа ограничены; данные других винтажей и других австралийских Vermentino не считаются эквивалентными.\n\nVermentino обычно отличается яркой цитрусово-травяной свежестью, лёгкой солоноватостью и умеренным телом; конкретные ароматические характеристики этой партии требуют подтверждения по первичному источнику. По этой позиции используются только подтверждённые сведения; неподтверждённые детали технологии и происхождения не переносятся из других винтажей. Юридический производитель, точный регион, ABV и схема винификации для этой партии требуют дополнительного подтверждения по первичному источнику.","producer_description":"Igor Larionov — винный бренд, связанный с Игорем Ларионовым, однако это не классический семейный австралийский домен с подробно опубликованной историей виноградников и погреба. Для этой конкретной позиции в открытых источниках нет достаточной первичной документации, чтобы надёжно описать владельца виноградника, площадь участка, возраст лоз или имя винодела.\n\nПозиция относится к бренду Igor Larionov и партнёрской винодельне; конкретное поместье в доступных источниках не подтверждено. Бренд на фронтальной этикетке и фактический производитель или bottler могут быть разными сущностями. Название австралийской производственной площадки, адрес розлива и точный регион в доступных первичных источниках не подтверждены, поэтому биографические детали конкретной винодельни остаются ограниченными.","price":5900,"glass_price":"","id":"2022-vermentino-igor-larionov-partnerskaya-vinodelnya","image":"","price_label":"5 900 ₽","glass_price_label":""},{"sheet":"Белое","row":4,"year":"2023","title":"Riesling Venture","producer":"Georg Breuer / Weingut Bernhard Mehrlein","category":"Белое сухое, тихое","region":"Германия, Rheingau","country":"Германия","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"Riesling","taste":"Лёгкое, свежее и гастрономичное; выразительный баланс кислотности и мягкой фруктовой округлости.","aroma":"Цитрус, зелёное яблоко, белый персик, лёгкие цветочные и минеральные оттенки.","color":"Светло-соломенный.","pairing":"Аперитив, салаты, рыба, морепродукты, блюда азиатской кухни с умеренной остротой.","description":"Venture Riesling 2023 — сухой Riesling из Rheingau, сделанный как совместный проект Georg Breuer и Weingut Bernhard Mehrlein. Виноград собирают с нескольких участков в разных деревнях Rheingau, поэтому задача вина — не показать один конкретный cru, а собрать узнаваемый региональный профиль: цитрус, яблоко, белые цветы, прохладную минеральность и высокую кислотность. Грозди прессуют целиком; ферментация проходит в нейтральной среде, преимущественно в нержавеющей стали, после чего вино остаётся там примерно восемь месяцев. Отсутствие заметного нового дуба сохраняет прозрачность сорта и «нерв» Riesling.\n\nВино разливается у Bernhard Mehrlein, а стилистическое участие команды Breuer связывает его с более строгой, сухой традицией Rüdesheim. Стиль вина определяется сочетанием факторов: прохладный Rheingau + Riesling + нейтральные ёмкости = яркая кислотность, цитрус и минерал, а не ваниль/тосты. В торговых источниках разных рынков показатели крепости могут меняться вместе с винтажом и конкретным релизом.","producer_description":"Georg Breuer — одно из наиболее узнаваемых хозяйств Rheingau, базирующееся в Rüdesheim. Репутация дома связана прежде всего с сухими Riesling и знаменитыми кру Rüdesheimer Berg; современное развитие хозяйства много лет ассоциируется с семьёй Breuer и Терезой Breuer. Философия — не максимальная мощность, а точность, кислотность и выражение каменистых склонов Rheingau.\n\nVenture отличается от estate-вина тем, что это совместный проект: виноград и розлив связаны с Weingut Bernhard Mehrlein из Oestrich-Winkel, а команда Georg Breuer участвует в создании стиля. Это показательный пример того, как имя сильного производителя может обозначать стилистическое авторство, а не обязательно собственный single vineyard.","price":6700,"glass_price":1150,"id":"2023-riesling-venture-georg-breuer-weingut-bernhard-mehrlein","image":"","price_label":"6 700 ₽","glass_price_label":"1 150 ₽"},{"sheet":"Белое","row":5,"year":"2024","title":"Chardonnay Les Grands Terroirs René Lequin-Colin","producer":"Domaine René Lequin-Colin","category":"Белое сухое, тихое; Vin de France","region":"Франция, Бургундия","country":"Франция","abv":"12.5%","volume":"750 мл","grapes":"Chardonnay","taste":"Свежий, сухой и округлый стиль с чистой фруктовостью, умеренной кислотностью и мягкой текстурой.","aroma":"Яблоко, груша, цитрус, белые цветы; возможны лёгкие сливочные нюансы.","color":"Светло-золотистый.","pairing":"Белая рыба, морепродукты, птица, мягкие сыры, сливочные соусы.","description":"Chardonnay Les Grands Terroirs — Vin de France от Domaine René Lequin-Colin. Официальный материал хозяйства описывает участок площадью около 1,4 га, заложенный в 2012 году, на каменистом плато с преобладанием известняка. Именно известковая почва помогает объяснить сочетание зрелого жёлтого фрукта с ощущением свежести и сухого минерального финиша. После ферментации/винификации вино выдерживают 14–16 месяцев: примерно 50% в ёмкостях и 50% в бочках, причём лишь около 10% бочек новые. Такая схема важна стилистически: дуб даёт объём, ванильные и сливочные оттенки, но небольшая доля нового дерева не должна превращать вино в «дубовую бомбу».\n\nОфициальное описание подчёркивает золотистый цвет, ваниль, цветок тиаре и жёлтые фрукты. Это показательный пример современного бургундского Chardonnay вне престижного аппелласьона: серьёзная работа с участком и выдержкой, но формально Vin de France. Категория на этикетке здесь не отражает напрямую уровень амбиций винодела: формально это Vin de France, но подход к участку и выдержке остаётся серьёзным.","producer_description":"Domaine René Lequin-Colin — семейное хозяйство в Santenay на Côte de Beaune. Семьи Lequin и Colin имеют глубокие бургундские корни; домен работает с участками в Santenay, Chassagne-Montrachet, Pommard и других коммунах. Важная особенность — стремление показывать различия участков через раздельную винификацию и умеренное использование нового дуба.\n\nLes Grands Terroirs стоит отдельно от классической лестницы Bourgogne/communal/1er Cru: это Chardonnay под категорией Vin de France, позволяющий хозяйству работать свободнее с происхождением и стилем. Производитель интересен как пример небольшого Côte de Beaune domaine, где даже «неклассифицированное» вино получает длительную выдержку и терруарный подход, характерный для более серьёзных бургундских кюве.","price":7200,"glass_price":1200,"id":"2024-chardonnay-les-grands-terroirs-rené-lequin-colin-domaine-rené-lequin-colin","image":"","price_label":"7 200 ₽","glass_price_label":"1 200 ₽"},{"sheet":"Белое","row":6,"year":"2024","title":"Sauvignon Blanc The Whale Watcher","producer":"Boutinot","category":"Белое сухое, тихое","region":"Новая Зеландия, Nelson","country":"Новая Зеландия","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"Sauvignon Blanc","taste":"Яркий и свежий: цитрусовая кислотность, сочность крыжовника, чистый сухой финиш и лёгкая морская минеральность.","aroma":"Крыжовник, лайм и другие цитрусовые, свежая зелень; ароматический профиль яркий, но не тяжёлый.","color":"Бледно-соломенный с зеленоватым оттенком.","pairing":"Устрицы, креветки, салаты, козий сыр, белая рыба, блюда с зеленью и цитрусом.","description":"The Whale Watcher Sauvignon Blanc 2024 — новозеландский Sauvignon Blanc в свежем, ароматном стиле. Для линейки Boutinot описывает классическую схему: мягкое прессование, холодное отстаивание сусла, перелив и прохладная ферментация на отобранных дрожжах; после этого отдельные партии смешивают, фильтруют и рано разливают, чтобы удержать первичную фруктовость. Такой метод логично объясняет яркие цитрусовые, тропические и травянистые ноты, высокую кислотность и отсутствие выраженного дуба.\n\nВ международных источниках линейка The Whale Watcher встречается с указанием Nelson и Marlborough в зависимости от конкретного релиза и винтажа. Региональная маркировка может различаться между релизами одной линейки. Стиль: чистый, прохладно ферментированный Sauvignon, рассчитанный на яркую ароматику и освежающую подачу. По стилю это более яркий и ароматный Sauvignon Blanc, чем минеральные и сдержанные Sancerre или Pouilly-Fumé.","producer_description":"The Whale Watcher выпускается в портфеле Boutinot — британской винной группы, которая работает как négociant, производитель и партнёр виноделен в разных странах.\n\nBoutinot активно создаёт региональные проекты и закупает/отбирает виноград или вино у партнёров, контролируя стиль и качество. Для The Whale Watcher задача — показать легко узнаваемый новозеландский Sauvignon Blanc: чистый фрукт, травянистую свежесть и высокую кислотность. Указание конкретного bottler или subregion относится к соответствующей партии и может быть точнее общей информации о линейке.","price":7300,"glass_price":1250,"id":"2024-sauvignon-blanc-the-whale-watcher-boutinot","image":"","price_label":"7 300 ₽","glass_price_label":"1 250 ₽"},{"sheet":"Белое","row":7,"year":"2024","title":"Ballet Blanc Галицкий и Галицкий","producer":"Галицкий & Галицкий","category":"Белое сухое, тихое","region":"Россия, Краснодарский край","country":"Россия","abv":"13%","volume":"750 мл","grapes":"Riesling, Chardonnay, Sauvignon Blanc; точные доли винтажа 2024 — сверить по этикетке/техлисту.","taste":"Сухое, свежее, с цитрусово-фруктовым ядром, заметной кислотностью и аккуратной текстурой.","aroma":"Цитрус, яблоко, белые цветы, травянистые и минеральные нюансы.","color":"Светло-соломенный.","pairing":"Рыба, морепродукты, салаты, свежие сыры, птица.","description":"Ballet Blanc 2024 — белый ассамбляж Riesling, Chardonnay и Sauvignon Blanc из Краснодарского края, ЗГУ «Кубань. Анапа». Виноградники расположены на мягком склоне примерно 250–300 м над уровнем моря, ориентировочно в 30 км от Чёрного моря и окружены лесом; сочетание высоты и ночного охлаждения помогает сохранять кислотность. Сорта винифицируют раздельно. Riesling и Sauvignon Blanc работают прежде всего на свежесть и ароматичность и выдерживаются в стали; Chardonnay частично проходит через нержавеющую сталь, частично — через французские бургундские pièce 228 л второго использования.\n\nДалее компоненты созревают около 11 месяцев на тонком осадке, а готовое вино получает дополнительную бутылочную выдержку около трёх месяцев. Поэтому Ballet Blanc сочетает лайм, крыжовник и маракуйю с более округлой текстурой Chardonnay и лёгкой солоноватостью. Для 2024 подтверждена крепость 13%; точные доли сортов производитель в доступном техлисте не публикует. Riesling и Sauvignon Blanc формируют свежесть и ароматичность, тогда как Chardonnay добавляет объём и более округлую текстуру.","producer_description":"«Галицкий & Галицкий» — небольшое семейное винодельческое хозяйство в Краснодарском крае. В актуальном профильном источнике для Ballet Blanc 2024 указано около 14 га действующих виноградников; проект планирует расширение посадок. Владельцем является Сергей Галицкий, а винодельческим направлением руководит Алексей Толстой. Первый релиз вин под маркой «Красная Горка» относится к 2018 году.\n\nПодход хозяйства строится на собственном винограде, ручном сборе, раздельной работе с сортами и точном использовании разных ёмкостей. Ballet Blanc хорошо показывает эту философию: Riesling и Sauvignon Blanc сохраняют свежесть в стали, а Chardonnay частично проходит через французские бургундские бочки 228 л, после чего компоненты долго работают на тонком осадке. Премиальный стиль проекта формируется за счёт контроля виноградника, ручного сбора, длительной выдержки и продуманного ассамбляжа, а не только за счёт известности владельца.","price":7800,"glass_price":1300,"id":"2024-ballet-blanc-galickiy-i-galickiy-galickiy-galickiy","image":"","price_label":"7 800 ₽","glass_price_label":"1 300 ₽"}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Белое","row":8,"year":"2023","title":"Etna Bianco","producer":"Alta Mora / Cusumano","category":"Белое сухое, тихое; Etna DOC","region":"Италия, Сицилия, Etna","country":"Италия","abv":"13%","volume":"750 мл","grapes":"100% Carricante","taste":"Сухое, энергичное и минеральное; свежая кислотность, цитрусово-грушевый профиль, солоноватый вулканический финиш.","aroma":"Лимон, груша, белые цветы, кремень и дымчато-минеральные нюансы.","color":"Светло-соломенный.","pairing":"Сырые и приготовленные морепродукты, белая рыба, паста с моллюсками, овощные блюда.","description":"Alta Mora Etna Bianco 2023 — 100% Carricante из Etna DOC. По техническому листу производителя виноград поступает с северного склона Этны: Castiglione di Sicilia, contrade Verzella и Pietramarina, а также Linguaglossa, contrada Arrigo. Лозы растут на высоте примерно 600–750 м, средний возраст виноградника около 15 лет; сбор ручной, в ящики, в первой декаде октября. Высота и вулканические почвы позволяют Carricante достигать полноценной зрелости, не теряя высокой кислотности и характерной солёно-минеральной линии.\n\nВинификация: мягкое прессование, статическое отстаивание, перелив; ферментация при 18–20 °C. Затем вино около 4 месяцев проводит в нержавеющей стали на тонком осадке и дополнительно созревает в бутылке. Сталь не добавляет дубовых ароматов, а осадок даёт текстуру. Крепость 13%. Сочетание факторов: Carricante + высота 600–750 м + вулканический терруар + сталь = цитрус, белые цветы, травы, солёность, высокая кислотность и каменистая минеральность. Это не «тяжёлая солнечная Сицилия», а прохладное вулканическое белое.","producer_description":"Alta Mora — этнийский проект семьи Cusumano, известной сицилийской винодельческой семьи. Для работы на Этне семья создала отдельную идентичность, потому что вулканические условия, высоты и местные сорта заметно отличаются от других зон Сицилии. Фокус Alta Mora — прежде всего Carricante для белых и Nerello Mascalese для красных, то есть местные сорта, которые лучше всего передают вулканический терруар.\n\nВиноградники распределены по contrade на разных экспозициях и высотах; хозяйство стремится сохранять кислотность и прозрачность происхождения, а не скрывать их активным новым дубом. Alta Mora показывает высокогорную, прохладную и минеральную сторону Сицилии, заметно отличающуюся от более тяжёлых южных стилей.","price":8900,"glass_price":1500,"id":"2023-etna-bianco-alta-mora-cusumano","image":"","price_label":"8 900 ₽","glass_price_label":"1 500 ₽"},{"sheet":"Белое","row":9,"year":"2024","title":"Vermentino Etichetta Nera","producer":"Lunae Bosoni","category":"Белое сухое, тихое; Colli di Luni DOC","region":"Италия, Лигурия / Colli di Luni","country":"Италия","abv":"13%","volume":"750 мл","grapes":"100% Vermentino","taste":"Сухое, гармоничное, солоноватое и устойчивое; зрелая фруктовость сочетается с пряностью и минеральной свежестью.","aroma":"Полевые цветы, травы, спелые фрукты, специи, лёгкие медовые оттенки.","color":"Интенсивный соломенно-жёлтый.","pairing":"Морепродукты, рыба, лигурийская кухня, паста с песто, овощи.","description":"Lunae Etichetta Nera Vermentino 2024 — 100% Vermentino из Colli di Luni DOC, пограничной зоны Лигурии и северной Тосканы между морем и Апуанскими Альпами. Для Etichetta Nera ежегодно выбирают наиболее выразительные участки; виноград собирают вручную ранним утром и быстро доставляют в погреб. По официальному техлисту ягоды проходят около 8 часов холодной мацерации с кожицей, затем сусло ферментирует при контролируемой температуре в нержавеющей стали. После ферментации вино примерно 4 месяца созревает на тонком осадке также в стали.\n\nЭта схема объясняет стиль: короткий контакт с кожицей усиливает аромат и текстуру Vermentino, осадок добавляет объём, а отсутствие дуба сохраняет чистые тона жёлтого персика и абрикоса, акации, средиземноморских трав, солёные и бальзамические нюансы. Крепость 13%. Финал длинный, миндальный и солоноватый. Etichetta Nera — серьёзный гастрономичный Vermentino, где сложность достигается отбором участков, короткой мацерацией и работой с осадком, а не новым дубом.","producer_description":"Cantine Lunae Bosoni — семейное хозяйство семьи Bosoni. Паоло Бозони унаследовал винодельческую традицию семьи и развивал современную Cantine Lunae с 1960-х годов; название Lunae отсылает к древнеримскому порту Luni и к историческому названию территории. Виноградники лежат между долиной реки Magra, Лигурийским морем и Апуанскими Альпами — сложный рельеф создаёт разные экспозиции и постоянную вентиляцию.\n\nХозяйство особенно известно работой с местными сортами и прежде всего Vermentino. Стиль Lunae строится на сочетании яркой средиземноморской ароматичности, солёности и чистой технологичной винификации. Etichetta Nera — одна из визитных карточек производителя и хороший пример того, как один сорт может быть серьёзным гастрономичным вином, а не только лёгким аперитивом.","price":9900,"glass_price":"","id":"2024-vermentino-etichetta-nera-lunae-bosoni","image":"","price_label":"9 900 ₽","glass_price_label":""},{"sheet":"Белое","row":10,"year":"2023","title":"Pouilly-Fumé de Ladoucette","producer":"Baron de Ladoucette / Château du Nozet","category":"Белое сухое, тихое; AOC Pouilly-Fumé","region":"Франция, Долина Луары, Pouilly-sur-Loire","country":"Франция","abv":"13%","volume":"750 мл","grapes":"100% Sauvignon Blanc","taste":"Среднетелое, сухое и свежее; сочная фруктовость, минеральность и характерный дымно-кремнистый акцент в длительном финише.","aroma":"Боярышник, цитрус, белый персик, манго; кремень и лёгкая йодистая нота.","color":"Бледно-золотистый с зеленоватым оттенком.","pairing":"Морепродукты, устрицы, белая рыба, козьи сыры, блюда с травами.","description":"Pouilly-Fumé de Ladoucette 2023 — 100% Sauvignon Blanc из Pouilly-sur-Loire на правом берегу Луары. В отличие от более экспрессивных «новосветских» Sauvignon, задача этого вина — показать каменистую, дымно-минеральную сторону сорта. Виноград собирают при оптимальной зрелости, проводят бережное прессование, затем ферментируют и выдерживают в нейтральных ёмкостях, преимущественно нержавеющей стали. Дом известен тем, что не спешит выпускать часть вин, давая им стабилизироваться до релиза.\n\nЭто сохраняет лимон, грейпфрут, белые цветы и травянистость, но добавляет текстуру и характерную для Pouilly-Fumé кремниевую/дымную ноту. В источниках по этому винтажу встречаются значения крепости 12,5–13%. От Sancerre это вино отличается прежде всего происхождением: другим берегом Луары, набором почв и собственной стилистикой Pouilly-Fumé. Характерные черты стиля — кремниево-дымная минеральность, сухость и сдержанная ароматичность.","producer_description":"Baron de Ladoucette — исторический дом, связанный с Château du Nozet в Pouilly-sur-Loire и одной из самых узнаваемых фамилий аппелласьона Pouilly-Fumé. Владения семьи в регионе имеют длинную историю; бренд Ladoucette стал международным ориентиром классического, отполированного Sauvignon Blanc Луары.\n\nПроизводитель работает с большими площадями и селекцией участков, выпускает как базовый Pouilly-Fumé de Ladoucette, так и более престижные кюве. В погребе стиль обычно чистый и технологически аккуратный: акцент на зрелом здоровом винограде, нейтральных ёмкостях и сохранении минеральной линии, а не на заметном новом дубе. Стиль Ladoucette отражает классический профиль Pouilly-Fumé: цитрус, белые цветы, травы, камень и кремень, сухой и собранный финиш.","price":13800,"glass_price":"","id":"2023-pouilly-fumé-de-ladoucette-baron-de-ladoucette-château-du-nozet","image":"","price_label":"13 800 ₽","glass_price_label":""},{"sheet":"Белое","row":11,"year":"2020","title":"Chardonnay Carneros Buena Vista","producer":"Buena Vista Winery","category":"Белое сухое, тихое","region":"США, California, Carneros","country":"США","abv":"14.5%","volume":"750 мл","grapes":"Chardonnay","taste":"Среднетелое и текстурное; лимонный крем, груша, свежее яблоко, аккуратный дуб и минеральная свежесть.","aroma":"Лимон, мандарин, косточковые фрукты, тост и лёгкие дубовые оттенки.","color":"Соломенно-золотистый.","pairing":"Лосось, гребешок, птица, сливочные пасты, мягкие сыры.","description":"Buena Vista Carneros Chardonnay 2020 происходит из прохладной зоны Carneros на юге Napa/Sonoma, где близость San Pablo Bay приносит туманы и ветер. Для Chardonnay это означает более медленное созревание и возможность совместить спелый калифорнийский фрукт с заметной кислотностью. Вино 2020 показывает более богатую стилистику: зрелое яблоко, груша, цитрус, сливочные/ванильные оттенки и объёмную текстуру. Винификация включает работу с дубом и осадком, поэтому во вкусе появляются кремовость, специи и округлость, но прохладный Carneros удерживает баланс. Крепость 14,5% указывает на полноценную зрелость винограда.\n\nПо стилю это контраст с Chablis или Loire: тот же Chardonnay, но климат и дуб переводят его из линейно-минерального профиля в более широкий, солнечный и текстурный.","producer_description":"Buena Vista Winery — историческая калифорнийская винодельня, основанная в 1857 году венгерским эмигрантом Агостоном Харасти, которого часто называют одним из пионеров коммерческого виноделия Калифорнии. Историческая винодельня находится в Sonoma. В современную эпоху Buena Vista входит в портфель Boisset Collection и продолжает использовать исторический образ дома, соединяя его с виноградом из разных калифорнийских зон.\n\nCarneros Chardonnay показывает работу не только с брендом Sonoma, но и с конкретным прохладным аппелласьоном. Buena Vista — один из старейших узнаваемых брендов Калифорнии; история хозяйства помогает объяснить heritage на этикетке, но конкретный характер вина всё равно задают Carneros и современная винификация.","price":14000,"glass_price":"","id":"2020-chardonnay-carneros-buena-vista-buena-vista-winery","image":"","price_label":"14 000 ₽","glass_price_label":""},{"sheet":"Белое","row":12,"year":"2022","title":"Ossian Viñas Viejas Blanco","producer":"Ossian Vides y Vinos","category":"Белое сухое, тихое","region":"Испания, Castilla y León","country":"Испания","abv":"13%","volume":"750 мл","grapes":"100% Verdejo","taste":"Сухое, плотное и структурное, но свежее; зрелые цитрусы и косточковые фрукты, пряность и минеральный, продолжительный финиш.","aroma":"Цитрус, жёлтое яблоко, персик, сушёные травы, специи и тонкая древесная нота.","color":"Соломенно-золотистый.","pairing":"Жирная рыба, морепродукты, птица, блюда с грибами, выдержанные сыры.","description":"Ossian Viñas Viejas 2022 — 100% Verdejo со старых лоз в Castilla y León, в районе исторических песчаных виноградников Segovia. Старые лоз на бедных песчаных почвах дают небольшой урожай и концентрированный виноград; часть таких участков сохранилась на собственных корнях благодаря песку, менее благоприятному для филлоксеры. Ossian сознательно показывает Verdejo не как лёгкое молодое Rueda, а как серьёзное белое с текстурой и потенциалом выдержки.\n\nВино ферментирует и созревает с использованием дубовых ёмкостей и длительной работы с осадком, поэтому цитрус, косточковый фрукт, травы и характерная горчинка Verdejo соединяются с кремовой структурой, пряностью и минеральностью. Крепость около 13%. В этой интерпретации Verdejo выходит далеко за рамки простого свежего вина: старые лозы, низкие урожаи и выдержка формируют сложное гастрономичное белое.","producer_description":"Ossian Vides y Vinos создавался вокруг идеи сохранения старых лоз Verdejo в провинции Segovia. Проект сделал ставку на очень старые, часто допрививочные лозы на песчаных почвах и на более «бургундский» подход к белому вину — ферментацию и выдержку по отдельным партиям, работу с осадком и умеренным дубом. Сегодня Ossian связан с группой Pago de Carraovejas, но сохраняет отдельную идентичность и фокус на Verdejo.\n\nХозяйство работает органически и рассматривает старые виноградники как главное наследие проекта. Ключевая мысль: ценность Ossian — не маркетинговое название, а редкий ресурс старых лоз и попытка доказать, что Verdejo способен на глубину, структуру и развитие в бутылке.","price":15600,"glass_price":"","id":"2022-ossian-viñas-viejas-blanco-ossian-vides-y-vinos","image":"","price_label":"15 600 ₽","glass_price_label":""},{"sheet":"Белое","row":13,"year":"2022","title":"Bourgogne Aligoté «Le Hardi» Domaine Ballorin","producer":"Domaine Ballorin & F.","category":"Белое сухое, тихое; AOC Bourgogne Aligoté","region":"Франция, Бургундия, Côte de Nuits","country":"Франция","abv":"13%","volume":"750 мл","grapes":"100% Aligoté (Aligoté Doré)","taste":"Очень сухое, прямое и энергичное; лимон, зелёное яблоко, сочная высокая кислотность и выраженная известняковая минеральность.","aroma":"Лимон, зелёное яблоко, цитрус, тонкие пряные и медовые нюансы.","color":"Золотисто-жёлтый; натуральная/маловмешательская стилистика может давать менее «глянцевый» вид.","pairing":"Морепродукты, рыба, jambon persillé, копчёная птица, спаржа.","description":"Bourgogne Aligoté «Le Hardi» 2022 сделан из Aligoté Doré — более редкого, мелкоягодного варианта Aligoté, который ценят за концентрацию. Вино связано с Côte de Nuits и показывает сорт не как нейтральную основу для kir, а как самостоятельное терруарное белое. Хозяйство работает органически/биодинамически, использует природные дрожжи и старается избегать агрессивной экстракции и лишнего технологического вмешательства. В результате Aligoté сохраняет высокую кислотность, лимонно-яблочную свежесть и солёно-минеральную линию, но получает больше текстуры и глубины.\n\nAligoté исторически считается «вторым белым сортом Бургундии» после Chardonnay, однако старые лозы, Aligoté Doré и серьёзный подход к винограднику способны давать вина высокой сложности. Крепость около 13%. Точная схема ёмкостей и длительность выдержки для винтажа 2022 требуют подтверждённого техлиста; данные соседних винтажей могут отличаться. Это показательный пример того, как репутация сорта может быть скромнее реального качества конкретного вина.","producer_description":"Domaine Ballorin & F. — небольшое хозяйство в Morey-Saint-Denis на Côte de Nuits, созданное Жилем Баллореном и Фабьенн. Домен известен ручной работой, органическим и биодинамическим подходом и стремлением минимально вмешиваться в вино. Производитель работает с Pinot Noir, Chardonnay и Aligoté на участках Côte de Nuits и соседних зон.\n\nВ погребе предпочитаются природные дрожжи, мягкая экстракция, умеренное использование серы и дуба; цель — не «сделать стиль винодела», а оставить различия участков читаемыми. Ballorin — пример современной ремесленной Бургундии: небольшой масштаб, экологичное земледелие, старые/интересные сорта и гораздо меньше полировки, чем у крупных négociant-домов. «Le Hardi» особенно хорошо показывает, что хозяйство серьёзно относится даже к категории Bourgogne Aligoté.","price":15800,"glass_price":"","id":"2022-bourgogne-aligoté-le-hardi-domaine-ballorin-domaine-ballorin-f","image":"","price_label":"15 800 ₽","glass_price_label":""},{"sheet":"Белое","row":14,"year":"2023","title":"Sancerre «Les Boucauds» Claude Riffault","producer":"Domaine Claude Riffault","category":"Белое сухое, тихое; AOC Sancerre","region":"Франция, Долина Луары, Sancerre","country":"Франция","abv":"14%","volume":"750 мл","grapes":"100% Sauvignon Blanc","taste":"Полнее классического лёгкого Sancerre: округлая текстура, сочная кислотность, лимонно-яблочный профиль, солоноватая минеральность и длинный финиш.","aroma":"Яблоко, консервированный лимон, сено, воск, минеральные и миндальные нюансы.","color":"Светло-соломенный.","pairing":"Козий сыр, устрицы, морской окунь, гребешок, спаржа, суши, паста с морепродуктами.","description":"Sancerre «Les Boucauds» 2023 — 100% Sauvignon Blanc с участков, где преобладают глинисто-известковые почвы. Такие почвы обычно дают Sancerre больше объёма и текстуры, чем самые кремнистые silex-участки, сохраняя при этом кислотность. Виноград собирают бережно, ферментация проходит на собственных дрожжах, а вино длительно созревает на тонком осадке — для Les Boucauds указывают примерно 14–16 месяцев. Осадок смягчает острую кислотность и добавляет кремовую плотность, поэтому вино выходит не только «цитрус и крыжовник», а более сложным: лимон, белые цветы, травы, спелый белый фрукт, мел и солёный минеральный финиш.\n\nКрепость около 14%. Les Boucauds — пример Sancerre, где терруар и выдержка на осадке важнее демонстративной ароматичности Sauvignon Blanc. В сравнении с новозеландским Sauvignon акцент смещён с тропиков и яркой зелени к меловой минеральности, плотности и гастрономичности.","producer_description":"Domaine Claude Riffault находится в Sury-en-Vaux в Sancerre и сегодня связан с семьёй Riffault, в частности со Стефаном Риффо. Хозяйство работает органически и уделяет большое внимание отдельным типам почв и экспозиций, выпуская несколько кюве Sauvignon Blanc и Pinot Noir. Виноградники обрабатываются так, чтобы поддерживать живые почвы; в погребе широко используются природные дрожжи и длительная выдержка на осадке.\n\nСтиль Riffault часто более текстурный и винный, чем у простых коммерческих Sancerre, при этом не теряет характерной кислотности и минеральности региона. Название Les Boucauds относится не просто к бренду, а к конкретному терруарному выражению Sancerre, прежде всего глинисто-известковому.","price":16500,"glass_price":"","id":"2023-sancerre-les-boucauds-claude-riffault-domaine-claude-riffault","image":"","price_label":"16 500 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Белое","row":15,"year":"2023","title":"Chablis Terroir Découverte","producer":"Patrick Piuze","category":"Белое сухое, тихое; AOC Chablis","region":"Франция, Бургундия, Chablis","country":"Франция","abv":"12%","volume":"750 мл","grapes":"100% Chardonnay","taste":"Чистое, сфокусированное и энергичное; лимон, яблоко, камень/мел, высокая свежесть и длинный минеральный финиш.","aroma":"Груша, яблоко, лимонный цвет, раковина устрицы, мел, тонкий восковой оттенок.","color":"Бледно-соломенный.","pairing":"Устрицы, морепродукты, белая рыба, суши, козий сыр.","description":"Chablis Terroir Découverte 2023 Патрика Пьюза — 100% Chardonnay, созданный как точное выражение конкретного участка. В материалах по этому кюве указывается виноградник Des Couverts, расположенный рядом с Premier Cru Vaulorent на северной стороне холма Grand Cru; прохладная экспозиция и воздушный коридор помогают сохранять кислотность, поэтому участок часто убирают поздно. В Chablis главное — не аромат дуба, а соединение зрелого Chardonnay с кимериджским известняком, высокой кислотностью и солёно-меловым послевкусием.\n\nПьюз работает с тщательно отобранным виноградом и винифицирует участки раздельно, чтобы различия terroir были заметны. Вино показывает лимон, зелёное/жёлтое яблоко, белые цветы и ракушечно-минеральные оттенки; крепость около 12%. Ключ — понимать слово «Terroir» буквально: это Chablis не как единый вкус, а как исследование отдельного происхождения.","producer_description":"Patrick Piuze — канадец по происхождению, построивший карьеру в Бургундии и ставший одним из заметных современных специалистов по Chablis. После работы в нескольких хозяйствах региона он запустил собственный проект в 2008 году. Пьюз в значительной степени работает как négociant-vinificateur: не обязательно владеет всеми виноградниками, но заключает долгосрочные отношения с growers, сам выбирает сроки сбора и контролирует качество фруктов.\n\nЕго подход — винифицировать участки отдельно и подчёркивать их различия, а не создавать единый «домовой» вкус. Поэтому линейка включает множество village, premier cru и grand cru с очень конкретным происхождением. Piuze — хороший пример того, что в Бургундии владение землёй и авторство вина не всегда одно и то же: решающими могут быть контроль сырья и работа винодела.","price":16900,"glass_price":"","id":"2023-chablis-terroir-découverte-patrick-piuze","image":"","price_label":"16 900 ₽","glass_price_label":""},{"sheet":"Белое","row":16,"year":"NV","title":"Tradition Heritage Cuvée 3 Years","producer":"Schloss Gobelsburg","category":"Белое сухое, тихое; multi-vintage / Tradition Heritage","region":"Австрия, Kamptal","country":"Австрия","abv":"13–13,5% — зависит от выпуска, сверить бутылку","volume":"750 мл","grapes":"Grüner Veltliner, Riesling; пропорции зависят от выпуска.","taste":"Плотное, сухое и сложное; зрелый цитрус, жёлтая слива, пряность, мелово-солоноватая минеральность и округлая текстура.","aroma":"Мирабель, лимонная цедра, воск, белый перец, дрожжево-ореховые и минеральные нюансы.","color":"Золотистый.","pairing":"Телятина, птица, жирная рыба, грибы, блюда со сливочными соусами, выдержанные сыры.","description":"Tradition Heritage Cuvée 3 Years Schloss Gobelsburg — необычное multi-vintage белое из Grüner Veltliner и Riesling, вдохновлённое методами виноделия XIX века. Это не обычное молодое Kamptal, где всё строится на первичной фруктовости. Сусло ферментирует спонтанно без жёсткого температурного контроля, а затем вино многократно переливают из бочки в бочку — историческая практика, при которой оно постепенно контактирует с кислородом и осветляется естественным образом. Базовые компоненты созревают минимум около трёх лет, отдельные — дольше; отсюда название Cuvée 3 Years.\n\nТакой метод формирует более «винный», сложный профиль: печёное яблоко, цитрус, травы, орех, воск, хлебные/пряные нюансы и солёная кислотность. Официальные выпуски Heritage обычно находятся около 13–13,5% об.; доли Grüner Veltliner и Riesling зависят от конкретного выпуска. Это мост между современной чистотой и историческим способом работы с белыми винами Австрии. Не называть его окисленным: контролируемый контакт с кислородом здесь часть стилистической концепции.","producer_description":"Schloss Gobelsburg — одно из старейших винодельческих хозяйств Австрии, расположенное в Kamptal. История виноградарства связана с монастырём Zwettl и уходит в средневековье; в современной эпохе хозяйством управляют Михаэль и Ева Моосбруггер. Основные сорта — Grüner Veltliner и Riesling, а ключевые виноградники включают знаменитые камтальские терруары вокруг Gobelsburg, Langenlois и Zöbing.\n\nДом сочетает точное современное земледелие с интересом к историческим методам погреба. Серия Tradition возникла как исследование того, как работали виноделы до появления нержавеющей стали, лабораторного контроля и постоянной защиты вина от кислорода. Schloss Gobelsburg важен не только как качественный австрийский производитель, но и как хозяйство, которое превращает историю технологии в отдельный осмысленный стиль.","price":17400,"glass_price":"","id":"nv-tradition-heritage-cuvée-3-years-schloss-gobelsburg","image":"","price_label":"17 400 ₽","glass_price_label":""},{"sheet":"Белое","row":17,"year":"2022","title":"Abtsberg Riesling Trocken GG Maximin Grünhaus","producer":"Weingut Maximin Grünhaus","category":"Белое сухое, тихое; VDP.Grosses Gewächs","region":"Германия, Mosel / Ruwer, Abtsberg","country":"Германия","abv":"12%","volume":"750 мл","grapes":"100% Riesling","taste":"Строгое, точное и концентрированное; сочная, но тонкая текстура, живая кислотность, пряная сланцевая минеральность и солоноватый долгий финиш.","aroma":"Персик, абрикос, цитрусовая цедра, травы, дым, цветочные и сланцевые оттенки.","color":"Светло-золотистый.","pairing":"Морепродукты, гребешки, тартар из лангустина, белая рыба, блюда с цитрусом и травами.","description":"Abtsberg Riesling Trocken GG 2022 — сухой Riesling категории VDP.Grosses Gewächs с одного из главных виноградников Maximin Grünhaus в долине Ruwer. Abtsberg — крутой исторический склон с девонским сланцем; бедные каменистые почвы быстро отводят воду и накапливают тепло, а прохладный Ruwer сохраняет кислотность. Вино ферментирует спонтанно и традиционно созревает в старых больших дубовых Fuder, которые дают не аромат нового дуба, а мягкую микрооксигенацию и текстуру.\n\nВино сухое, концентрированное, но не тяжёлое: цитрус, белый персик, зелёные травы, дымно-сланцевые оттенки и длинная солёная кислотность. Крепость около 12%. Статус GG означает сухое вино с виноградника высшей категории по классификации VDP. Связь терруара и стиля: Ruwer → прохладный климат; Abtsberg → сланец и исторический grand cru; GG → сухой топовый Riesling.","producer_description":"Maximin Grünhaus — историческое хозяйство в Ruwer, притоке Мозеля, ныне принадлежащее семье von Schubert, которая приобрела имение в 1882 году. Усадьба известна тремя монопольными историческими виноградниками — Abtsberg, Herrenberg и Bruderberg — непосредственно вокруг Grünhaus. Благодаря прохладному микроклимату Ruwer вина традиционно отличаются высокой кислотностью, травяно-минеральным характером и способностью долго развиваться.\n\nХозяйство сохраняет классические большие Fuder и спонтанные ферментации, сочетая их с современным контролем качества. Abtsberg считается самым престижным участком домена и имеет многовековую репутацию. Maximin Grünhaus — один из ориентиров классического немецкого Riesling, причём его стиль заметно отличается от более солнечных зон Rheingau или Pfalz.","price":26200,"glass_price":"","id":"2022-abtsberg-riesling-trocken-gg-maximin-grünhaus-weingut-maximin-grünhaus","image":"","price_label":"26 200 ₽","glass_price_label":""},{"sheet":"Белое","row":18,"year":"2022","title":"Cervaro della Sala Antinori","producer":"Marchesi Antinori — Castello della Sala","category":"Белое сухое, тихое; Umbria IGT","region":"Италия, Umbria, Castello della Sala","country":"Италия","abv":"13% (часть карточек указывает 12.5%; сверить по вашей бутылке)","volume":"750 мл","grapes":"85% Chardonnay, 15% Grechetto","taste":"Полнотелое и тонкое; цитрус и ананас, сливочная текстура, минеральность, ванильно-ореховые оттенки и свежий структурный финиш.","aroma":"Цитрус, ананас, акация, ваниль и кремень.","color":"Бледно-жёлтый с зеленоватым оттенком.","pairing":"Рыба, ракообразные и моллюски, белое мясо, паста с белым рагу, грибы.","description":"Cervaro della Sala 2022 — флагманское белое Castello della Sala: купаж преимущественно Chardonnay с меньшей долей Grechetto. Виноград выращивают на холмах Умбрии на глинисто-известковых почвах, богатых морскими ископаемыми; высота 220–470 м и суточные перепады температуры помогают удерживать кислотность. Chardonnay собирают раньше Grechetto. После примерно четырёх часов прохладной мацерации сусло Chardonnay осветляют и отправляют в баррики, где проходит алкогольная и частичная малолактическая ферментация. Grechetto винифицируют отдельно и без дубовой выдержки, чтобы сохранить местную свежесть и травянистость; затем компоненты соединяют и вино дополнительно созревает в бутылке.\n\nИменно эта технология объясняет стиль: зрелый цитрус, белые цветы, дымок/кремень, ваниль, лимонное масло и выпечка, но при этом заметная кислотность. Cervaro — одно из первых известных итальянских белых, где малолактика и выдержка Chardonnay проходили в барриках. Это не просто «итальянский Chardonnay», а исторически важная модель итальянского белого международного класса с местным Grechetto.","producer_description":"Castello della Sala — умбрийское поместье семьи Antinori недалеко от Orvieto. Средневековый замок и земли занимают около 600 га, из которых примерно 229 га засажены виноградниками. Белые сорта здесь особенно успешны благодаря высоте, глинисто-известковым почвам с морскими ископаемыми и сильной разнице дневных и ночных температур.\n\nCervaro della Sala родился в 1985 году под руководством Ренцо Котареллы и стал одним из наиболее известных итальянских белых вин с потенциалом выдержки. Marchesi Antinori — одна из старейших винодельческих семей Италии, работающая с вином с XIV века и владеющая хозяйствами в Тоскане, Умбрии и других регионах. Cervaro — пример того, как Antinori адаптировали бургундские методы к собственному терруару, а не просто скопировали стиль Chardonnay.","price":32900,"glass_price":"","id":"2022-cervaro-della-sala-antinori-marchesi-antinori-castello-della-sala","image":"","price_label":"32 900 ₽","glass_price_label":""},{"sheet":"Белое","row":19,"year":"2019","title":"Chassagne-Montrachet 1er Cru Clos Saint-Jean Edouard Delaunay","producer":"Maison Edouard Delaunay","category":"Белое сухое, тихое; AOC Chassagne-Montrachet 1er Cru","region":"Франция, Бургундия, Côte de Beaune, Chassagne-Montrachet","country":"Франция","abv":"13.5%","volume":"750 мл","grapes":"100% Chardonnay","taste":"Богатое, текстурное и сложное; сливочно-шёлковое, с ванильно-пряными оттенками и минеральной кислотностью в финише.","aroma":"Спелые белые и жёлтые фрукты, ваниль, специи, сливочное масло, минеральные оттенки.","color":"Золотисто-соломенный.","pairing":"Лобстер, морской гребешок, белая рыба в сливочном соусе, птица, выдержанные сыры.","description":"Chassagne-Montrachet 1er Cru Clos Saint-Jean 2019 от Edouard Delaunay — 100% Chardonnay из Premier Cru в Côte de Beaune. Chassagne-Montrachet способен давать одновременно плотность и минеральное напряжение; 2019 был зрелым, солнечным годом, поэтому вино показывает щедрый фрукт и богатую текстуру. В дегустационных материалах винтажа отмечаются сливочность, шелковистость, специи, ваниль/дуб и при этом сохраняющая баланс минеральная кислотность. Крепость около 13,5%.\n\nДля Premier Cru такого уровня важна не просто «выдержка в бочке», а интеграция дуба: дерево должно поддерживать Chardonnay, добавляя объём и пряность, но не скрывать известковый терруар. Clos Saint-Jean — историческое climat Chassagne-Montrachet; название отражает три уровня происхождения: Burgundy → commune Chassagne-Montrachet → Premier Cru Clos Saint-Jean. Именно эта иерархия объясняет происхождение и ценность вина.","producer_description":"Maison Edouard Delaunay — исторический бургундский négociant-дом, основанный в конце XIX века. После периода, когда бренд находился вне семьи, Лоран Делоне — представитель нового поколения винодельческой семьи — выкупил и возродил Maison Edouard Delaunay в 2017 году. Современная стратегия дома — работа небольшими партиями с высококачественным виноградом/вином из разных аппелласьонов Бургундии, тщательная раздельная винификация и точная работа с дубом.\n\nКак и у других négociants, происхождение винограда и роль винодела здесь не всегда совпадают с владением участком. Производитель быстро вернул себе сильную репутацию за чистые, полированные и терруарные вина. Edouard Delaunay — пример возрождённого исторического négociant, а не одного семейного domaine с единственным массивом земли.","price":33000,"glass_price":"","id":"2019-chassagne-montrachet-1er-cru-clos-saint-jean-edouard-delaunay-maison-edouard-delaunay","image":"","price_label":"33 000 ₽","glass_price_label":""},{"sheet":"Белое","row":20,"year":"2023","title":"Meursault «La Barre Dessus» Rossignol-Cornu et Fils","producer":"Domaine Rossignol-Cornu et Fils","category":"Белое сухое, тихое; AOC Meursault","region":"Франция, Бургундия, Côte de Beaune, Meursault","country":"Франция","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"100% Chardonnay","taste":"Богатое и сложное, с зрелой фруктовостью, минеральной опорой и сливочно-дубовой текстурой при сохранённой свежести.","aroma":"Спелые белые фрукты, цитрус, орехово-сливочные и минеральные ноты.","color":"Золотисто-соломенный.","pairing":"Тюрбо, лобстер, гребешок, птица, телятина, сливочные соусы и выдержанные сыры.","description":"Meursault «La Barre Dessus» 2023 Domaine Rossignol-Cornu — 100% Chardonnay с маленького участка около 0,09 га в Meursault. Экспозиция юго-западная, почвы глинисто-известковые. Алкогольная и малолактическая ферментации проходят в бочках; затем вино проводит около девяти месяцев в дубе, примерно половина которого может быть новой, и ещё около трёх месяцев в стали на тонком осадке перед розливом. Эта комбинация объясняет стиль: дуб и малолактика дают орехово-сливочную текстуру, специи и объём, а финальная сталь и известковый терруар сохраняют собранность.\n\nУ Meursault нет Grand Cru, поэтому ценность строится на репутации коммуны и конкретных lieux-dits/1er Cru. La Barre Dessus — village-level lieu-dit, но очень маленький участок и серьёзная винификация делают его более индивидуальным, чем «усреднённый Meursault». Это показательный пример того, почему в Бургундии маленький географический нюанс может быть важнее сорта: Chardonnay один и тот же, но место и работа в погребе меняют стиль.","producer_description":"Domaine Rossignol-Cornu et Fils — семейное хозяйство Côte de Beaune, базирующееся в Volnay и работающее также с участками Meursault, Pommard и соседних коммун. Это классический бургундский семейный domaine: небольшие участки, много ручной работы и отдельная винификация по происхождению. В красных винах дом ориентирован на Pinot Noir, в белых — на Chardonnay; использование дуба зависит от уровня кюве и не должно перекрывать terroir.\n\nДля Meursault La Barre Dessus особенно показателен малый размер участка — около одной десятой гектара, поэтому объём производства естественно ограничен. Rossignol-Cornu не как глобальный бренд, а как ремесленное хозяйство, где ценность создаётся конкретной землёй и семейной работой с ней.","price":38000,"glass_price":"","id":"2023-meursault-la-barre-dessus-rossignol-cornu-et-fils-domaine-rossignol-cornu-et-fils","image":"","price_label":"38 000 ₽","glass_price_label":""},{"sheet":"Белое","row":22,"year":"2023","title":"Pinot Grigio","producer":"Livio Felluga","category":"Белое сухое, тихое; Friuli Colli Orientali DOC","region":"Италия, Friuli-Venezia Giulia","country":"Италия","abv":"13%","volume":"375 мл","grapes":"100% Pinot Grigio","taste":"Структурное и сбалансированное; сочный персик, папайя, яблоко, сушёный абрикос и шалфей, с солоноватым цитрусовым финишем.","aroma":"Абрикос, жёлтый персик, цветы, имбирь, травы, эвкалипт и кремень.","color":"Интенсивный соломенно-жёлтый с лёгкими золотисто-медными бликами.","pairing":"Рыба, моллюски, ризотто, запечённые овощи.","description":"Pinot Grigio 2023 Livio Felluga — 100% Pinot Grigio из Friuli Colli Orientali. Виноград собирают вручную, мягко прессуют после короткого контакта с кожицей, сусло осветляют и ферментируют при контролируемой температуре в нержавеющей стали. Затем вино несколько месяцев остаётся на тонком осадке, что добавляет округлость и сложность, не забирая сортовую свежесть. Поэтому стиль заметно серьёзнее простого массового Pinot Grigio: груша, яблоко, цитрус, белые цветы, лёгкая миндальная/минеральная нота и хорошая текстура.\n\nФормат позиции — 375 мл. Состав вина тот же, однако меньшая бутылка обычно эволюционирует немного быстрее из-за иного соотношения кислорода и объёма. Для 2023 в разных международных источниках встречается крепость около 13–13,5%. Pinot Grigio во Friuli способен быть гастрономичным и структурным благодаря холмистым участкам и более низким урожаям.","producer_description":"Livio Felluga — одно из знаковых имён Friuli-Venezia Giulia. После Второй мировой войны Ливио Феллуга восстанавливал заброшенные холмистые виноградники Friuli Colli Orientali и сыграл заметную роль в формировании современной репутации региона. Этикетки с картой территории стали фирменным знаком дома и визуально подчёркивают связь вина с местом.\n\nСемья продолжает управлять хозяйством; портфель включает местные и международные белые сорта, а также красные. Стиль обычно строится на чистоте фрукта, точной кислотности и работе с осадком, а не на агрессивном дубе в базовых белых. Livio Felluga отражает серьёзную сторону Friuli: регион известен не только лёгким Pinot Grigio, но и сложными белыми с текстурой и потенциалом.","price":5600,"glass_price":"","id":"2023-pinot-grigio-livio-felluga","image":"","price_label":"5 600 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Белое","row":23,"year":"2024","title":"Chablis Sainte Claire","producer":"Jean-Marc Brocard","category":"Белое сухое, тихое; AOC Chablis","region":"Франция, Бургундия, Chablis","country":"Франция","abv":"12.5% (часть карточек указывает 13%; сверить бутылку)","volume":"375 мл","grapes":"100% Chardonnay","taste":"Тонизирующее, сухое и минеральное; зелёное яблоко, лимон, меловые и каменистые ноты, хрустящая кислотность.","aroma":"Зелёное яблоко, лимон, мел, дроблёный камень.","color":"Бледно-соломенный.","pairing":"Устрицы, мидии, краб, гравлакс, свежие сыры, белая рыба.","description":"Chablis Sainte Claire 2024 Jean-Marc Brocard — 100% Chardonnay, классический региональный Chablis в чистом, минеральном стиле. Главный терруарный фактор — кимериджский известняк с морскими ископаемыми, который вместе с прохладным климатом даёт высокую кислотность и характерные мелово-ракушечные ассоциации. Sainte Claire винифицируют преимущественно в нержавеющей стали и держат на осадке, избегая заметного нового дуба: поэтому вино сохраняет лимон, зелёное яблоко, белые цветы и солёный финиш.\n\nВаша позиция — 375 мл. По крепости 2024 встречаются 12,5 и 13% в зависимости от рынка/формата, поэтому фактическая этикетка бутылки в ресторане имеет приоритет. Sainte Claire — хороший «эталонный» Chablis: понять Chardonnay без ванили и тостов, где структура создаётся кислотностью, известняком и осадком, а не дубом.","producer_description":"Domaine Jean-Marc Brocard — крупное и влиятельное хозяйство Chablis, основанное Жан-Марком Брокаром в 1970-х. Дом вырос до значительного портфеля от Petit Chablis до Grand Cru и одним из первых в регионе широко экспериментировал с органическим и биодинамическим земледелием на части участков. Сегодня семейная команда продолжает подчёркивать чистоту и минеральность Chardonnay, часто используя сталь и минимальное вмешательство в базовых кюве.\n\nЛинейка Sainte Claire связана с более экологичным подходом хозяйства и выражением классического Chablis без тяжёлого дуба. Brocard — крупный производитель Chablis, который при значительном масштабе уделяет большое внимание почвам и устойчивым практикам.","price":5800,"glass_price":"","id":"2024-chablis-sainte-claire-jean-marc-brocard","image":"","price_label":"5 800 ₽","glass_price_label":""},{"sheet":"Белое","row":24,"year":"2024","title":"Ronco del Cerò Sauvignon Blanc","producer":"Venica & Venica","category":"Белое сухое, тихое; Collio DOC","region":"Италия, Friuli-Venezia Giulia, Collio","country":"Италия","abv":"13.5%","volume":"375 мл","grapes":"100% Sauvignon Blanc","taste":"Свежий, солоноватый, хорошо структурированный и стойкий; чистая кислотность и выразительная ароматическая отдача.","aroma":"Крыжовник, бергамот, гуава, маракуйя, лист чёрной смородины, самшит, травы и минеральные нюансы.","color":"В молодости зеленоватые оттенки переходят в насыщенный соломенно-жёлтый.","pairing":"Овощные равиоли, креветки на гриле с лаймом, цветы цукини, гребешок, лосось с травами.","description":"Ronco del Cerò Sauvignon 2024 Venica & Venica — 100% Sauvignon Blanc из Collio DOC. Название связано с холмом Ronco del Cerò, участком, приобретённым семьёй ещё в 1929 году. Виноград поступает с нескольких участков, которые винифицируют раздельно, чтобы учесть разную зрелость и экспозиции. Venica уделяет большое внимание защите сусла от чрезмерного кислорода: в процессе используют инертную среду, в том числе повторно применяя CO₂, образующийся при ферментации. Это помогает сохранить тонкие летучие ароматы Sauvignon — бузину, шалфей, цитрус, белый персик — без грубой «зелёности».\n\nПосле сборки вино получает текстуру и солёно-минеральный финиш, характерный для Collio. Крепость около 13,5%. Формат позиции — 375 мл; по стилю это то же кюве, при этом маркировка и параметры конкретной партии могут отличаться. В сравнении с Loire Sauvignon здесь больше зрелости, травяно-фруктовой ширины и средиземноморского ощущения.","producer_description":"Venica & Venica — семейное хозяйство в Dolegna del Collio, основанное в 1930 году. Семья работает с виноградниками на холмах Collio у границы со Словенией. Регион известен ponca — мергелево-песчаниковыми почвами, хорошей вентиляцией и большим суточным перепадом температур, что особенно подходит ароматическим белым сортам.\n\nVenica специализируется на Sauvignon, Friulano, Pinot Grigio и других белых, часто выделяя конкретные ronco/участки. Современная работа хозяйства сочетает семейную традицию с точной технологией: контроль кислорода, раздельная работа с участками и бережное сохранение ароматики. Ronco del Cerò — одна из наиболее известных белых этикеток дома и хороший пример серьёзного Sauvignon из Friuli, отличного по стилю от Луары и Новой Зеландии.","price":10500,"glass_price":"","id":"2024-ronco-del-cerò-sauvignon-blanc-venica-venica","image":"","price_label":"10 500 ₽","glass_price_label":""},{"sheet":"Красное","row":3,"year":"2023","title":"Pinot Noir Freiherr von Göler Burg Ravensburg","producer":"Weingut Burg Ravensburg","category":"Красное сухое, тихое; QbA Baden","region":"Германия, Baden","country":"Германия","abv":"13%","volume":"750 мл","grapes":"100% Pinot Noir","taste":"Мягкое, сочное и сбалансированное; красные ягоды, тонкая пряность, шелковистые танины и свежий финиш.","aroma":"Клубника, вишня, красная смородина, лёгкий дым и специи.","color":"Прозрачный рубиновый.","pairing":"Утка, птица, телятина, грибы, мягкие сыры.","description":"Freiherr von Göler Pinot Noir 2023 — 100% Pinot Noir из Baden, юго-запада Германии. Вино относится к более лёгкому, прохладному стилю сорта: красная вишня, клубника, красная смородина, травяная пряность, мягкие танины и свежая кислотность. В профильных материалах для линейки упоминаются участки Kraichgau с гипсом, мергелем и песчаником. Винификация намеренно не перегружена новым дубом: задача — сохранить прозрачный красный фрукт и сортовую деликатность, а не сделать мощное «бургундское подобие». Крепость около 12,5–13% в зависимости от партии; фактическая этикетка ресторана приоритетна.\n\nНемецкое название сорта Spätburgunder: в Германии Pinot Noir исторически важен, а потепление климата и точная работа с участками сделали Baden одним из сильнейших регионов страны для красного. Это вино — доступная точка входа в немецкий Pinot: сочность и кислотность важнее концентрации.","producer_description":"Weingut Burg Ravensburg — историческое хозяйство в Baden, связанное с замком Ravensburg в Kraichgau и многовековой традицией виноградарства. Поместье относится к числу старых немецких винодельческих владений и сегодня известно работой с Riesling, Pinot Noir и другими сортами на известняково-мергелевых и гипсовых почвах.\n\nВина ориентированы на чистоту происхождения и баланс, а не на чрезмерную экстракцию. Для Pinot Noir это означает аккуратную работу с дубом и сохранение прохладного красноягодного профиля. Название Freiherr von Göler/Burg Ravensburg связано с историческим поместьем и семьёй, владевшей им, а не с отдельной новой винодельней. Производитель интересен как пример аристократического немецкого estate, где терруар Kraichgau и Pinot Noir формируют альтернативу более известным бургундским стилям.","price":6600,"glass_price":1100,"id":"2023-pinot-noir-freiherr-von-göler-burg-ravensburg-weingut-burg-ravensburg","image":"","price_label":"6 600 ₽","glass_price_label":"1 100 ₽"},{"sheet":"Красное","row":4,"year":"2024","title":"Мерло","producer":"Temerinda","category":"Красное сухое, тихое","region":"Россия, Краснодарский край","country":"Россия","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"Merlot","taste":"Параметры конкретного винтажа 2024 требуют сверки по техлисту производителя/этикетке.","aroma":"Не заполнялось типовыми дескрипторами без подтверждения конкретной партии.","color":"Рубиновый — сверить фактическую бутылку.","pairing":"После сверки: мясо на гриле, птица, паста с мясным соусом, полутвёрдые сыры.","description":"Temerinda Merlot 2024 — российское сухое красное из Merlot, позиция из Краснодарского края. В открытых материалах производителя описывается терруар Таманского полуострова и работа с собственными виноградниками; для винтажа 2024 отдельные детали остаются неполностью подтверждёнными, а крепость и параметры выдержки могут различаться между партиями. Merlot обычно даёт здесь спелую вишню, сливу и тёмные ягоды, мягкие танины и округлое тело. В работе с сортом важен контроль зрелости: слишком ранний сбор даёт травянистость и жёсткость, слишком поздний — тяжёлую джемовую стилистику.\n\nПо стилю это современный российский Merlot, а не попытка воспроизвести типичный Bordeaux. Происхождение из южного российского терруара и более мягкая танинная структура по сравнению с Cabernet Sauvignon. Крепость, точный способ ферментации, доля нового дуба и длительность выдержки для винтажа 2024 в открытых первичных источниках требуют дополнительного подтверждения.","producer_description":"Temerinda — российский винодельческий проект на Таманском полуострове, связанный с Евгением и Анной Шумаковыми; в профессиональных публикациях в качестве главного винодела упоминается Владислав Шевченко. Проект делает акцент на собственных виноградниках и работе с международными сортами в условиях сухого и ветреного южного терруара.\n\nTemerinda — молодое современное российское хозяйство без заявленной вековой истории. Стиль проекта формируется через конкретные решения на винограднике и в погребе. Сведения о площади виноградников, возрасте лоз и точной схеме выдержки Merlot 2024 в доступных первичных источниках пока ограничены.","price":7500,"glass_price":"","id":"2024-merlo-temerinda","image":"","price_label":"7 500 ₽","glass_price_label":""},{"sheet":"Красное","row":5,"year":"2022","title":"Syrah","producer":"Mantra Estate","category":"Красное сухое, тихое","region":"Россия, Краснодарский край, район Крымска","country":"Россия","abv":"около 11% — сверить по бутылке","volume":"750 мл","grapes":"100% Syrah","taste":"Сухое, пряное и структурное; красно-тёмная фруктовость, мягкие танины, оттенки кожи и ванили.","aroma":"Сушёная вишня, красные ягоды, лесная подстилка, роза, кожа, ваниль и специи.","color":"Глубокий рубиновый.","pairing":"Говядина, ягнёнок, мясо на гриле, утка, выдержанные сыры.","description":"Mantra Estate Syrah 2022 — 100% Syrah из района Крымска/Лефкадийской долины в Краснодарском крае. Для вина описан конкретный участок около 3 га с северной экспозицией; более прохладная ориентация помогает Syrah сохранять кислотность и перечную свежесть в южном климате. Виноград собирали в два срока, чтобы соединить более свежую и более зрелую фракции. После ферментации вино выдерживали примерно 11 месяцев: около 67% объёма в нержавеющей стали и 33% во французском дубе. Эта пропорция хорошо объясняет стиль — вино остаётся ягодным и перечным, без чрезмерной ванили, но часть дуба добавляет округлость, дымно-пряные тона и структуру.\n\nДля винтажа 2022 встречается крепость около 11%, что делает его особенно интересным на фоне более плотных южных Syrah. Стиль напрямую связан с решениями винодела: северная экспозиция + два срока сбора + преимущественно сталь = свежесть; меньшая доля дуба = текстура и специи. Это позволяет объяснять вино не через набор ароматов, а через причину их появления.","producer_description":"Mantra Estate — молодой российский винный проект в Краснодарском крае, работающий с небольшими партиями и участками, где можно управлять экспозицией и сроками сбора. Публичной исторической информации о хозяйстве меньше, чем у старых европейских доменов, поэтому наиболее надёжно описываются конкретные технические данные каждого кюве.\n\nНа примере Syrah 2022 видно осознанное управление стилем: выбор северной экспозиции, раздельные сроки сбора и смешанная выдержка в стали и французском дубе. Это показывает современный подход к южнороссийскому терруару — не стремиться только к максимальной зрелости, а удерживать баланс и пряную сортовую свежесть. Mantra Estate относится к новой волне российских проектов, где стиль формируется через конкретные решения по экспозиции, срокам сбора и выдержке.","price":7800,"glass_price":1300,"id":"2022-syrah-mantra-estate","image":"","price_label":"7 800 ₽","glass_price_label":"1 300 ₽"},{"sheet":"Красное","row":6,"year":"2023","title":"Poggio ai Ginepri","producer":"Tenuta Argentiera","category":"Красное сухое, тихое; Toscana IGT","region":"Италия, Тоскана, Bolgheri","country":"Италия","abv":"13.5% — встречаются карточки с иным значением; сверить этикетку","volume":"750 мл","grapes":"40% Cabernet Sauvignon, 30% Merlot, 20% Cabernet Franc, 10% Petit Verdot","taste":"Сочное и отполированное; чёрная смородина, ежевика и слива, умеренная свежесть, гладкие танины, табачно-пряный финиш.","aroma":"Чёрные ягоды, слива, кедр, чёрный перец, табак и кожа.","color":"Глубокий рубиновый.","pairing":"Стейк, рагу, паста с рагу, запечённое мясо, твёрдые сыры.","description":"Poggio ai Ginepri 2023 — красный тосканский купаж Tenuta Argentiera из зоны Bolgheri: 40% Cabernet Sauvignon, 30% Merlot, 20% Cabernet Franc и 10% Petit Verdot. Это бордосская композиция, адаптированная к тёплому средиземноморскому побережью. Разные сорта созревают в разное время и дают разные роли: Cabernet Sauvignon — каркас и чёрную смородину, Merlot — округлость и сливовый фрукт, Cabernet Franc — ароматическую свежесть, Petit Verdot — цвет, специи и танины.\n\nПосле ферментации часть вина созревает в дубе, часть — в более нейтральных ёмкостях, поэтому Poggio ai Ginepri остаётся доступным и фруктовым, не превращаясь в тяжёлое барричное вино. В источниках по винтажу 2023 встречаются различия в показателе крепости. Стиль Bolgheri здесь формируют морской климат, международные сорта и умеренное использование дуба.","producer_description":"Tenuta Argentiera находится в Bolgheri на тосканском побережье, в южной части знаменитой зоны. Поместье получило название от старых серебряных рудников региона; виноградники расположены на возвышенностях с видом на море и получают выраженное средиземноморское влияние. Хозяйство сосредоточено прежде всего на Cabernet Sauvignon, Merlot, Cabernet Franc и Petit Verdot — сортах, которые сделали Bolgheri известным за пределами традиционного Sangiovese.\n\nPoggio ai Ginepri — более доступное кюве, тогда как Argentiera и другие вина занимают более высокий уровень. Производитель помогает понять Bolgheri как отдельную тосканскую модель: здесь идентичность строится не на Chianti/Brunello и чистом Sangiovese, а на прибрежном терруаре и бордосских сортах.","price":8600,"glass_price":1400,"id":"2023-poggio-ai-ginepri-tenuta-argentiera","image":"","price_label":"8 600 ₽","glass_price_label":"1 400 ₽"},{"sheet":"Красное","row":7,"year":"2021","title":"Chianti Classico","producer":"Rocca di Montegrossi","category":"Красное сухое, тихое; Chianti Classico DOCG","region":"Италия, Тоскана, Chianti Classico","country":"Италия","abv":"14%","volume":"750 мл","grapes":"92% Sangiovese, 6% Canaiolo, 2% Colorino","taste":"Свежий, сочный и savoury; кислая вишня, лесные ягоды, живая кислотность и тонко очерченные танины.","aroma":"Дикая ягода, вишня, фиалка, травы и землистые нюансы.","color":"Рубиновый с фиолетовым оттенком.","pairing":"Паста с рагу, bistecca, блюда из свинины, томатные соусы, пекорино.","description":"Chianti Classico Rocca di Montegrossi 2021 — купаж 92% Sangiovese, 6% Canaiolo и 2% Colorino. Виноградники хозяйства находятся в Monti in Chianti на глинисто-известковых и мергелистых почвах. Урожай собирают вручную и проводят несколько проходов, чтобы получить ягоды оптимальной зрелости. Sangiovese формирует вишню, кислотность и танинную основу; Canaiolo добавляет мягкость и аромат, Colorino — цвет и структуру. После ферментации вино выдерживают примерно год в крупных или умеренно воздействующих дубовых ёмкостях, затем дополнительно в бутылке.\n\nДуб здесь не должен звучать громче Sangiovese: главные маркеры — кислая вишня, фиалка, травы, земля, специи, яркая кислотность и сухие танины. Крепость около 14%. Chianti Classico DOCG отличается от Chianti происхождением из исторической зоны между Florence и Siena, символикой Gallo Nero и более строгими правилами производства. В гастрономии кислотность делает вино особенно удобным для томатных соусов, пасты, мяса и выдержанных сыров.","producer_description":"Rocca di Montegrossi — историческое поместье в Monti in Chianti, связанное с семьёй Ricasoli-Firidolfi и давней тосканской винодельческой традицией. Современное хозяйство развивал Марко Рикасоли-Фиридольфи. Виноградники находятся в сердце Chianti Classico, а земледелие сертифицировано как органическое; большое внимание уделяется Sangiovese и местным сортам.\n\nДомен работает как estate и делает линейку от Chianti Classico до более серьёзных Riserva/Gran Selezione и IGT. Стиль — классический, структурный и гастрономичный, с умеренным дубом и акцентом на кислотность Sangiovese. Rocca di Montegrossi — хороший контрапункт «международной» Тоскане Bolgheri: здесь главное — местный сорт, историческая зона и традиционная тосканская структура.","price":9100,"glass_price":"","id":"2021-chianti-classico-rocca-di-montegrossi","image":"","price_label":"9 100 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Красное","row":8,"year":"2022","title":"Sela","producer":"Bodegas Roda","category":"Красное сухое, тихое; Rioja DOCa","region":"Испания, Rioja","country":"Испания","abv":"13,5%","volume":"750 мл","grapes":"89% Tempranillo, 7% Garnacha, 4% Graciano","taste":"Сочное и современное Rioja: красные и тёмные ягоды, свежая кислотность, аккуратные танины и пряный финиш.","aroma":"Вишня, ежевика, фиалка, специи, лёгкий дуб.","color":"Яркий рубиново-вишнёвый.","pairing":"Тапас, charcuterie, ягнёнок, свинина, блюда на гриле.","description":"Sela 2022 Bodegas Roda — Rioja DOCa, точный купаж 89% Tempranillo, 7% Garnacha и 4% Graciano. Виноград происходит с лоз примерно 15–30 лет, урожай собирают вручную в небольшие ящики и сортируют. Алкогольная ферментация проходит спонтанно, а малолактическая — в французских дубовых чанах; затем вино около 12 месяцев выдерживают во французском дубе второго использования. Вторичная бочка важна: она даёт кислород и округляет танины, но не перегружает молодое фруктовое кюве ванилью.\n\nВино естественно стабилизируют и традиционно осветляют яичным белком. Крепость около 13,5%. В стиле сочетаются вишня, красная/чёрная ягода, сладкие специи, свежая кислотность и мягкий танин. Sela задуман как более ранний и доступный Rioja от Roda, но техника остаётся серьёзной. Это пример современной Rioja, где фрукт и чистота участка важнее долгой окислительной выдержки. Хорошо сравнивать его с Viña Tondonia в этой же карте.","producer_description":"Bodegas Roda основана в конце 1980-х в Haro, Rioja Alta. Хозяйство создавалось с идеей изучать отдельные участки старых лоз и каждый год собирать из них купажи по стилю урожая. В отличие от традиционной системы Rioja, где акцент часто делается на категории выдержки и длительное созревание в американском дубе, Roda работает более терруарно: ручной сбор, тщательная селекция, французский дуб и внимание к текстуре фруктов.\n\nКлючевые вина — Roda, Roda I, Cirsion; Sela — более молодая и доступная интерпретация той же философии. Стиль Roda относится к современной Rioja: меньше окислительности, больше свежего фрукта, точной зрелости и французского дуба.","price":9300,"glass_price":"","id":"2022-sela-bodegas-roda","image":"","price_label":"9 300 ₽","glass_price_label":""},{"sheet":"Красное","row":9,"year":"2023","title":"Bourgogne Pinot Noir","producer":"Domaine François Chapuis","category":"Красное сухое, тихое; Bourgogne","region":"Франция, Бургундия","country":"Франция","abv":"12.5%","volume":"750 мл","grapes":"100% Pinot Noir","taste":"Гибкое, фруктовое и тонкотанинное; красная вишня и ягоды, свежесть, лёгкая перечность.","aroma":"Красные фрукты, чёрная вишня, цветочные оттенки.","color":"Чистый ярко-красный.","pairing":"Птица, паштеты, телятина, грибы, мягкие сыры.","description":"Bourgogne Pinot Noir 2023 Domaine François Chapuis — 100% Pinot Noir из Бургундии. Категория Bourgogne не указывает конкретную коммуну уровня Gevrey или Volnay, поэтому задача — дать чистый региональный образ Pinot Noir: красная вишня, малина, клубника, цветы, лёгкая земля и специи, умеренное тело и свежая кислотность. Винификация традиционная, с акцентом на мягкую экстракцию, чтобы сохранить тонкость сорта, а не строить тяжёлый танинный профиль.\n\nКрепость около 12,5% подчёркивает не тяжёлую, а прозрачную стилистику. Bourgogne Pinot Noir занимает региональный уровень бургундской иерархии: он ниже village, Premier Cru и Grand Cru по географической точности, но способен хорошо показывать характер сорта и региона. Профиль строится на finesse, красном фрукте и кислотности, а не на плотности Cabernet или Syrah. В паре с едой Pinot Noir хорош там, где нужна деликатность: птица, телятина, грибы, утка.","producer_description":"Domaine François Chapuis — бургундское хозяйство, представленное на профессиональных органических винных площадках; производитель работает с Pinot Noir и Chardonnay и ориентируется на экологичные практики. В публичных источниках биографическая история домена, дата основания и площадь хозяйства раскрыты ограниченно.\n\nПодтверждаемая ценность — работа в Бургундии, органическое направление и классическая малотиражная винификация. Не все интересные Bourgogne происходят от «звёздных» имён: небольшие производители нередко ярко показывают сорт и базовую региональную категорию. Конкретная деревня или участок в доступных источниках не подтверждены.","price":9500,"glass_price":1600,"id":"2023-bourgogne-pinot-noir-domaine-françois-chapuis","image":"","price_label":"9 500 ₽","glass_price_label":"1 600 ₽"},{"sheet":"Красное","row":10,"year":"2022","title":"Valpolicella Ripasso","producer":"Buglioni","category":"Красное сухое, тихое; Valpolicella Ripasso Classico Superiore","region":"Италия, Veneto, Valpolicella Classica","country":"Италия","abv":"13.5%","volume":"750 мл","grapes":"60% Corvina, 20% Corvinone, 10% Rondinella, 5% Croatina, 5% Oseleta","taste":"Тёплое, бархатистое и гармоничное; зрелая вишня и слива, сладкие специи, табак, мягкие танины и продолжительный финиш.","aroma":"Спелые красные/тёмные фрукты, специи, ваниль и табак.","color":"Глубокий рубиновый.","pairing":"Рагу, полента с мясом, утка, свинина, выдержанные сыры.","description":"Valpolicella Ripasso «Il Bugiardo» 2022 Buglioni — 60% Corvina, 20% Corvinone, 10% Rondinella, 5% Croatina и 5% Oseleta. Сначала получают сухую Valpolicella, затем её повторно запускают на мезге после производства Amarone — это и есть техника ripasso. Второй контакт с кожицей добавляет цвет, тело, глицерин, сушёно-фруктовые и пряные оттенки, но вино остаётся легче Amarone. После ripasso кюве выдерживают около 12 месяцев в крупных славонских дубовых бочках 25–50 гл, а общая выдержка до выпуска составляет примерно 20 месяцев.\n\nВиноград органический и собирается вручную; участки расположены в Valpolicella Classica на тёмных глинисто-гравийных почвах. Крепость около 13,5%. Ripasso — не сорт и не «мини-Amarone», а технологический метод повторной ферментации/мацерации на выжимках Amarone, который создаёт промежуточный стиль. Вкус обычно соединяет свежую вишню Valpolicella с более сушёными, пряными и шоколадными оттенками.","producer_description":"Buglioni — семейная винодельня из Valpolicella, история которой началась сравнительно недавно по меркам Veneto: семья приобрела сельский дом с виноградником и постепенно превратила проект в полноценное хозяйство. Бренд любит характерные, немного ироничные названия кюве; «Il Bugiardo» переводится как «лжец» и отсылает к тому, что вино настолько насыщенно, что «притворяется Amarone».\n\nВиноградники сертифицированы органически, а хозяйство работает с традиционными сортами Valpolicella — Corvina, Corvinone, Rondinella и др. В погребе сочетаются ripasso/appassimento и крупный славонский дуб, то есть производитель опирается на региональную традицию, а не на интенсивный новый баррик. Buglioni работает в классической технологической логике региона: Valpolicella → Ripasso → Amarone.","price":11400,"glass_price":1900,"id":"2022-valpolicella-ripasso-buglioni","image":"","price_label":"11 400 ₽","glass_price_label":"1 900 ₽"},{"sheet":"Красное","row":11,"year":"2022","title":"Bourgogne Pinot Noir Naïma Didon","producer":"Naïma & David Didon","category":"Красное сухое, тихое; Bourgogne","region":"Франция, Бургундия","country":"Франция","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"100% Pinot Noir","taste":"Тонкое и энергичное; вишня, лесная малина, перец, земля, тонкие танины, солоноватая свежесть.","aroma":"Фиалка, анис, османтус, красные и чёрные ягоды, специи.","color":"Прозрачный рубиновый.","pairing":"Птица, утка, грибы, телятина, блюда с корнеплодами.","description":"Bourgogne Pinot Noir 2022 Naïma & David Didon — натуральная/биодинамическая интерпретация Pinot Noir. Виноград собирают вручную; в погребе используют высокий процент целых гроздей, мягкое раздавливание и спонтанную ферментацию на природных дрожжах. Мацерация длится примерно две недели, затем вино созревает в старых tonneaux около 9–10 месяцев. Старый дуб почти не добавляет ванили, зато даёт медленную микрооксигенацию; целые грозди добавляют цветочно-пряные, стеблевые оттенки и делают танин более вертикальным.\n\nПоэтому стиль — живой, прозрачный: вишня, лесная ягода, фиалка, специи, земля, сочная кислотность и лёгкая естественная «дикость», но без тяжести. В источниках по винтажу указывается крепость около 12,5%. Low-intervention характер вина формируют биодинамический виноград, целые грозди, природные дрожжи, старый дуб и минимальное использование серы.","producer_description":"Naïma и David Didon — небольшое бургундское хозяйство, связанное с Côte de Beaune и современной волной органического/биодинамического виноделия. Дэвид Дидон имеет опыт работы в известных бургундских доменах, после чего пара развила собственные участки и микропроизводство. Основные принципы — живые почвы, ручная работа, природные дрожжи, минимум коррекций, старый дуб и очень умеренное использование серы.\n\nОбъёмы небольшие, а вина востребованы среди любителей натуральной Бургундии. Стиль производителя определяется не только ярлыком «natural», а прежде всего качеством винограда и точной работой с целыми гроздями и экстракцией. Это ремесленный контраст более крупным и полированным négociant-домам.","price":15600,"glass_price":"","id":"2022-bourgogne-pinot-noir-naïma-didon-naïma-david-didon","image":"","price_label":"15 600 ₽","glass_price_label":""},{"sheet":"Красное","row":12,"year":"2020","title":"«Семейное наследие»","producer":"Сикоры","category":"Красное сухое, тихое","region":"Россия, Краснодарский край","country":"Россия","abv":"14%","volume":"750 мл","grapes":"Cabernet Franc, Cabernet Sauvignon, Красностоп, Merlot","taste":"Плотное и структурное; тёмные ягоды, специи и дубовые оттенки, зрелые танины и длинный финиш.","aroma":"Чёрная смородина, вишня, слива, специи, кедр/дуб.","color":"Глубокий рубиново-гранатовый.","pairing":"Стейк, дичь, ягнёнок, тушёная говядина, твёрдые сыры.","description":"«Семейное наследие» 2020 Имения Сикоры — выдержанный красный ассамбляж Cabernet Franc, Cabernet Sauvignon, Красностопа и Merlot. Виноград происходит из Семигорья/района Новороссийска. Ягоды полностью отделяют от гребней; каждый сорт ферментируют отдельно в нержавеющей стали с контролем температуры, а окончательный купаж формируют после оценки компонентов. Вино выдерживают около 18 месяцев во французских барриках, затем ещё несколько месяцев в стали; перед выходом на рынок оно получает длительную бутылочную выдержку.\n\nПоэтому профиль соединяет чёрную смородину, вишню, тёмную сливу и ягоды с шоколадом, кожей, кофе и зрелыми дубовыми специями. Крепость около 14%. Особенно интересен Красностоп: местный сорт включён в бордосскую структуру, придавая купажу российскую идентичность. Стиль строится на сочетании международной структуры Cabernet/Merlot с локальной ролью Красностопа и не сводится к копированию Bordeaux.","producer_description":"«Имение Сикоры» — премиальное хозяйство в Семигорье, Краснодарский край, связанное с Александром Сикорским. Виноградники расположены в континентальном микроклимате с жарким сухим летом и более прохладными периодами; почвы включают каменисто-мергелевые компоненты. Хозяйство стало одним из заметных проектов, сформировавших репутацию Семигорья как серьёзного российского терруара.\n\nБольшое внимание уделяется ручной селекции, раздельной винификации сортов и длительной выдержке во французском дубе. «Семейное наследие» — ассамблированное вино хозяйства, где российский Красностоп помещён рядом с международными Cabernet/Merlot. Сикоры — пример российского estate, где ставка сделана на выдержанные сухие вина и потенциал развития, а не только на молодую фруктовость.","price":16200,"glass_price":"","id":"2020-semeynoe-nasledie-sikory","image":"","price_label":"16 200 ₽","glass_price_label":""},{"sheet":"Красное","row":13,"year":"2022","title":"Malbec Bramare","producer":"Viña Cobos","category":"Красное сухое, тихое","region":"Аргентина, Mendoza, Luján de Cuyo","country":"Аргентина","abv":"14.9%","volume":"750 мл","grapes":"Malbec","taste":"Насыщенное и объёмное; слива, ежевика, зрелые танины, пряность и долгий, бархатистый финиш.","aroma":"Слива, ежевика, фиалка, специи, лёгкие древесные оттенки.","color":"Глубокий фиолетово-рубиновый.","pairing":"Стейк, асадо, ягнёнок, тушёное мясо, твёрдые сыры.","description":"Bramare Malbec Luján de Cuyo 2022 — 100% Malbec из одного из исторических высококачественных районов Mendoza. Luján de Cuyo расположен у подножия Анд; высота, сухой климат и большой суточный перепад температур помогают Malbec накапливать цвет и зрелый фрукт, сохраняя кислотность. Вино плотное и зрелое: ежевика, слива, фиалка, какао, специи, графит, сладкий дуб и заметные, но спелые танины. Высокая крепость около 14,9% отражает солнечную зрелость; более прохладная подача и контакт с воздухом помогают сохранить баланс.\n\nBramare — не простое молодое Malbec: выдержка в дубе и работа с более концентрированным сырьём делают стиль структурным и рассчитанным на гастрономию и выдержку. По сравнению с европейскими красными: здесь фрукт шире и спелее, но высота Анд даёт свежесть и баланс.","producer_description":"Viña Cobos — аргентинский проект, основанный американским виноделом Полом Хоббсом вместе с аргентинскими партнёрами в Mendoza. Хоббс сыграл заметную роль в международном признании современного Malbec: идея состояла в том, чтобы соединить старые и качественные аргентинские виноградники, точный контроль зрелости и современную работу с дубом.\n\nПортфель включает несколько уровней — от Felino до Bramare и топовых Cobos; Bramare относится к более серьёзной терруарной линии. Хозяйство работает в Luján de Cuyo и Valle de Uco, подчёркивая различия высоты и почв. Viña Cobos показывает Malbec высокого уровня: сорт здесь способен передавать конкретные зоны Mendoza и развиваться в бутылке.","price":16500,"glass_price":"","id":"2022-malbec-bramare-viña-cobos","image":"","price_label":"16 500 ₽","glass_price_label":""},{"sheet":"Красное","row":14,"year":"2012","title":"Viña Tondonia Reserva R. López de Heredia","producer":"R. López de Heredia Viña Tondonia","category":"Красное сухое, тихое; Rioja DOCa Reserva","region":"Испания, Rioja Alta, Haro","country":"Испания","abv":"13%","volume":"750 мл","grapes":"70% Tempranillo, 20% Garnacha, 5% Graciano, 5% Mazuelo","taste":"Сухое, мягкое и округлое; зрелая красная фруктовость, высокая свежесть, деликатные танины и очень длинный сложный финиш.","aroma":"Цитрус и сушёный инжир, апельсиновая корка, орех, ваниль, карамель, табак и развитые третичные ноты.","color":"Яркий рубиновый с лёгким янтарным оттенком.","pairing":"Холодные мясные закуски, грибы, мягкие и выдержанные сыры, красное мясо, дичь, птица.","description":"Viña Tondonia Reserva 2012 — классическая Rioja Alta от López de Heredia: 70% Tempranillo, 20% Garnacha, 5% Graciano и 5% Mazuelo. Виноград происходит с исторического Viña Tondonia на правом берегу Ebro, с аллювиальными, глинисто-известковыми и гравийными почвами; многие лозы старые. После отделения гребней вино ферментирует с кожицей в больших старых дубовых чанах. Затем начинается главное: около шести лет выдержки в старых американских бочках с регулярными переливами примерно дважды в год.\n\nПеред розливом традиционно используют осветление свежим яичным белком; вино не строится на аромате нового дуба, а развивается через длительную мягкую оксидацию. Отсюда сушёная вишня, красная ягода, кожа, табак, чай, ваниль, лес, специи и тонкая кислотность. Крепость около 13%. Tondonia — эталон традиционной Rioja и идеальный контраст современной фруктовой Roda/Sela. Длительная выдержка формирует третичные ароматы, которые являются частью стиля вина, а не признаком дефекта.","producer_description":"R. López de Heredia Viña Tondonia — один из самых традиционных домов Rioja, основанный в Haro в 1877 году. Семья по-прежнему владеет и управляет хозяйством, что редко для столь исторического бренда. У производителя собственные знаменитые виноградники, включая Viña Tondonia, Bosconia, Cubillo и Gravonia; в погребах используются старые большие чаны и огромное количество выдержанных американских бочек.\n\nХозяйство сознательно сохраняет методы XIX–XX веков: очень длительная бочковая и бутылочная выдержка, регулярные переливы, минимум модных технологических изменений. Вина выходят на рынок гораздо позже большинства конкурентов. López de Heredia — обязательный ориентир: традиционная Rioja — это не просто «много американского дуба», а долгое созревание, развитие третичных ароматов и удивительная свежесть даже в зрелом возрасте.","price":17000,"glass_price":"","id":"2012-viña-tondonia-reserva-r-lópez-de-heredia-r-lópez-de-heredia-viña-tondonia","image":"","price_label":"17 000 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Красное","row":15,"year":"2020","title":"Barolo","producer":"Giacomo Fenocchio","category":"Красное сухое, тихое; Barolo DOCG","region":"Италия, Piemonte, Barolo","country":"Италия","abv":"14.5%","volume":"750 мл","grapes":"100% Nebbiolo","taste":"Структурное, сухое и свежее; красная вишня, лакрица, пряность, выраженные, но тонкие танины и длинный финиш.","aroma":"Роза, фиалка, вишня, сушёные травы, лакрица и специи.","color":"Гранатовый, с возрастом светлеющий по краю.","pairing":"Тушёная говядина, дичь, трюфельные блюда, зрелые сыры.","description":"Barolo 2020 Giacomo Fenocchio — 100% Nebbiolo, классический Barolo DOCG. Nebbiolo поздно созревает и сочетает сравнительно светлый цвет с высокой кислотностью и мощными танинами. Поэтому Barolo строится не на густоте цвета, а на структуре и ароматической сложности: красная вишня, сушёная роза, фиалка, лакрица, чай, земля, специи и постепенно появляющиеся табачно-кожаные оттенки. Для Fenocchio характерен традиционный подход: длительная мацерация и выдержка в крупных нейтральных бочках, где древесина не должна давать сладкую ваниль нового баррика. Крепость винтажа около 14,5%.\n\nЭто сравнительно молодой Barolo с хорошим потенциалом развития; декантация помогает раскрыть аромат и смягчить восприятие танинов. Ключевая особенность: Barolo = Nebbiolo + высокая кислотность + выраженный танин + очень ароматичный нос. Светлый рубиново-гранатовый цвет не означает лёгкость.","producer_description":"Giacomo Fenocchio — семейное хозяйство в Monforte d’Alba, одна из традиционалистских виноделен Barolo. Семья работает с Nebbiolo на нескольких известных участках, включая Bussia, Cannubi, Villero и другие cru, и выпускает как отдельные single-vineyard Barolo, так и более широкий Barolo. Стиль хозяйства опирается на длительные мацерации и крупные старые славонские дубовые бочки, а не на выраженный новый баррик.\n\nЭто помогает сохранить аромат Nebbiolo и различия между MGA/участками. Домен остаётся семейным и сравнительно небольшим; его стиль отражает классическую Langhe, где виноградник и традиционная выдержка важнее технологической полировки. Fenocchio — хороший контрапункт более модернистским Barolo, где дуб может быть заметнее.","price":20900,"glass_price":"","id":"2020-barolo-giacomo-fenocchio","image":"","price_label":"20 900 ₽","glass_price_label":""},{"sheet":"Красное","row":16,"year":"2022","title":"Physalis Pinot Noir Pierre Frick","producer":"Domaine Pierre Frick","category":"Красное сухое, тихое; натуральное/биодинамическое","region":"Франция, Alsace","country":"Франция","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"Pinot Noir","taste":"Требует сверки по конкретному техлисту 2022; ожидаемый профиль не перенесён из других винтажей.","aroma":"Требует сверки по конкретному винтажу.","color":"Рубиновый — сверить фактическую бутылку.","pairing":"После сверки: птица, грибы, charcuterie, блюда из свинины.","description":"Physalis Pinot Noir 2022 Pierre Frick — натуральный/биодинамический Pinot Noir из Alsace. Для линейки Physalis подтверждаются Pinot Noir и биодинамическое происхождение; в источниках по 2022 встречается крепость около 13% и указание на минимальное использование или отсутствие добавленной серы. Точные детали мацерации для винтажа 2022 в открытых источниках подтверждены не полностью; опубликованные сведения описывают прежде всего общий стиль Domaine Frick.\n\nВино по концепции ближе к живому, маломанипулированному Pinot Noir: сочный красный и тёмный фрукт, земля, специи, умеренные танины, свежая кислотность; возможна естественная лёгкая мутность или более «дикая» ароматика. Натуральный характер вина связан с биодинамическим виноградом, спонтанными процессами, минимумом корректировок и очень осторожной работой с SO₂.","producer_description":"Domaine Pierre Frick — семейное хозяйство в Pfaffenheim, Alsace, одно из ранних и известных французских имён биодинамики. Семья Frick давно работает органически, а затем перешла к биодинамическим принципам и сертификации Demeter. В погребе хозяйство стремится к минимальному вмешательству: природные дрожжи, отсутствие лишних корректировок, очень низкие дозы серы или отдельные кюве без её добавления.\n\nПроизводитель работает с традиционными эльзасскими сортами и Pinot Noir, а также экспериментирует с мацерацией и стилями. Physalis относится к более натуральной, свободной части портфеля. У Frick биодинамика относится прежде всего к земледелию, а «натуральность» вина дополнительно определяется решениями в погребе; это разные, хотя и связанные понятия.","price":20900,"glass_price":"","id":"2022-physalis-pinot-noir-pierre-frick-domaine-pierre-frick","image":"","price_label":"20 900 ₽","glass_price_label":""},{"sheet":"Красное","row":17,"year":"2020","title":"Châteauneuf-du-Pape Classique Mas Saint Louis","producer":"Domaine Mas Saint Louis","category":"Красное сухое, тихое; AOC Châteauneuf-du-Pape","region":"Франция, Rhône, Châteauneuf-du-Pape","country":"Франция","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"Grenache (доминирует), Syrah, Mourvèdre, Cinsault; Guide Hachette для 2020 указывает 80% Grenache.","taste":"Сочное и средне-полнотелое; чёрная ягода, перечность, цветочные оттенки, мягкая атака, тонкие танины и минеральный, savoury финиш.","aroma":"Свежая черника, зелёный перец, цветы, сухие травы и специи.","color":"Глубокий рубиновый.","pairing":"Ягнёнок с травами, кролик, дичь, тушёное мясо, выдержанные сыры.","description":"Châteauneuf-du-Pape Classique 2020 Mas Saint Louis — Grenache-доминантный южноронский купаж; для этого винтажа профильные источники указывают около 80% Grenache, остальные компоненты включают Syrah, Mourvèdre и Cinsault. Grenache приносит спелую вишню, малину, сушёные травы и высокий алкоголь; Syrah — цвет и перец, Mourvèdre — танин и мясистые/землистые нюансы, Cinsault — ароматическую лёгкость. Выдержка проходит в нейтральных ёмкостях и крупных foudre, чтобы дуб не заглушал garrigue и зрелый фрукт.\n\nChâteauneuf-du-Pape известен галечными почвами galets roulés, которые аккумулируют дневное тепло, хотя конкретные участки хозяйства могут включать несколько типов почв. Это пример традиционной южной Rhône: купаж, Grenache, травы garrigue, специи и тепло вместо сортовой «чистоты».","producer_description":"Domaine Mas Saint Louis — семейное хозяйство Châteauneuf-du-Pape, работающее с традиционными южноронскими сортами и несколькими участками аппелласьона. Производитель делает ставку на Grenache как основу классического красного стиля, а выдержку ведёт преимущественно в более нейтральных крупных ёмкостях, чтобы сохранить плод и травянистую специфику terroir.\n\nВ отличие от современных очень дубовых интерпретаций, Mas Saint Louis ближе к традиционному образу Châteauneuf: зрелость, пряность, garrigue и мягкое развитие в бутылке. Аппелласьон разрешает широкий набор сортов, но конкретный дом формирует собственный купаж; поэтому нельзя автоматически перечислять «все сорта Châteauneuf» как состав каждой бутылки.","price":23400,"glass_price":"","id":"2020-châteauneuf-du-pape-classique-mas-saint-louis-domaine-mas-saint-louis","image":"","price_label":"23 400 ₽","glass_price_label":""},{"sheet":"Красное","row":18,"year":"2020","title":"Clos Martinet","producer":"Mas Martinet","category":"Красное сухое, тихое; DOQ Priorat","region":"Испания, Catalunya, Priorat","country":"Испания","abv":"около 14.5% — сверить этикетку","volume":"750 мл","grapes":"Syrah, Garnacha, Cariñena, Merlot, Cabernet Sauvignon; опубликованные доли 2020 расходятся, поэтому без процентов.","taste":"Глубокое и концентрированное, но элегантное; тёмный фрукт, цветочно-бальзамические ноты, минералы licorella, зрелые танины и длинный финиш.","aroma":"Ежевика, слива, цветы, травы, бальзамические и минерально-каменистые оттенки.","color":"Глубокий рубиново-пурпурный.","pairing":"Ягнёнок, говядина, дичь, тушёные блюда, выдержанные сыры.","description":"Clos Martinet 2020 — флагман Mas Martinet и показательное выражение современного Priorat. Виноград происходит с крутых склонов вокруг Gratallops, где корни пробиваются через licorella — бедный тёмный сланец, главный геологический маркер региона. В опубликованных материалах по 2020 встречается купаж с доминированием Syrah и значимыми долями Garnacha и Cariñena; разные источники расходятся по точным процентам, поэтому состав приводится без долей.\n\nФерментация проходит с минимальным вмешательством в бетонных и керамических ёмкостях, а последующая выдержка около 18 месяцев распределяется между крупным foudre и бетонными «яйцами». Это даёт концентрацию без избытка нового дуба: ежевика, слива, средиземноморские травы, бальзамические и сланцево-минеральные оттенки, плотная, но свежая структура. Licorella — ключевой геологический маркер Priorat; современный стиль региона всё чаще смещается от тяжёлой барричной концентрации к более прозрачному выражению сланца и местных сортов.","producer_description":"Mas Martinet — одно из хозяйств, стоявших у современного возрождения Priorat в конце XX века. Проект связан с семьёй Pérez; сегодня важную роль играет Сара Перес — одна из наиболее заметных фигур каталонского виноделия. Виноградники расположены вокруг Gratallops на крутых сланцевых склонах licorella.\n\nСовременная философия хозяйства сместилась от мощных «международных» вин 1990-х к более экологичной работе, органике/регенеративным практикам, местным сортам и меньшему влиянию нового дуба. Clos Martinet остаётся флагманом, но сегодня его сила — не только концентрация, а баланс, энергия и выражение сланца. Mas Martinet — хороший пример эволюции Priorat: от суперконцентрированного стиля к более свежему и терруарному.","price":25400,"glass_price":"","id":"2020-clos-martinet-mas-martinet","image":"","price_label":"25 400 ₽","glass_price_label":""},{"sheet":"Красное","row":19,"year":"2020","title":"Brunello di Montalcino","producer":"Le Chiuse","category":"Красное сухое, тихое; Brunello di Montalcino DOCG","region":"Италия, Тоскана, Montalcino","country":"Италия","abv":"около 14.5%","volume":"750 мл","grapes":"100% Sangiovese (Brunello)","taste":"Структурное и элегантное; красная вишня и слива, травянистая свежесть, заметные, тонкие танины и длинный бальзамический финиш.","aroma":"Красная вишня, слива, фиалка, травы, бальзамические и землистые нюансы.","color":"Гранатово-рубиновый.","pairing":"Бистекка, ягнёнок, дичь, выдержанный pecorino, блюда с трюфелем.","description":"Brunello di Montalcino 2020 Le Chiuse — 100% Sangiovese Grosso, местное название/биотип Sangiovese, используемый для Brunello. Вино происходит с высококачественных участков Montalcino и строится на традиционной длительной выдержке, где крупный дуб даёт кислород, но не должен ароматизировать вино как новый баррик. Sangiovese здесь раскрывается как кислая и спелая вишня, сухие травы, фиалка, кожа, чай, табак и землистые оттенки; высокая кислотность и сухие танины обеспечивают долголетие.\n\nВинтаж 2020 уже способен к питью после воздуха, но рассчитан и на развитие. Крепость обычно около 14,5%. Brunello — не отдельный сорт от Sangiovese, а выражение Sangiovese из Montalcino с жёсткими правилами происхождения и выдержки. Le Chiuse особенно интересно как классически построенный, не перегруженный новым дубом стиль.","producer_description":"Le Chiuse — небольшое семейное хозяйство в Montalcino с очень значимой историей: часть виноградников ранее была связана с владениями семьи Biondi-Santi, создавшей классический образ Brunello. Современное Le Chiuse развивалось как самостоятельный estate, сохранив фокус на Sangiovese Grosso и традиционной выдержке.\n\nХозяйство работает небольшими объёмами и делает Brunello, Rosso di Montalcino и ограниченные кюве; стиль обычно элегантный, кислотный и рассчитанный на старение, а не на максимальную дубовую сладость. Le Chiuse — хороший мост к истории Brunello: вино показывает историческую связь с классической школой Montalcino, но является самостоятельным современным производителем.","price":28500,"glass_price":"","id":"2020-brunello-di-montalcino-le-chiuse","image":"","price_label":"28 500 ₽","glass_price_label":""},{"sheet":"Красное","row":20,"year":"2022","title":"Gevrey-Chambertin Aurélien Verdet","producer":"Domaine Aurélien Verdet","category":"Красное сухое, тихое; AOC Gevrey-Chambertin","region":"Франция, Бургундия, Côte de Nuits, Gevrey-Chambertin","country":"Франция","abv":"13%","volume":"750 мл","grapes":"100% Pinot Noir","taste":"Плотное для Pinot Noir, но точное; вишня и клубника, мясистая середина, хорошая танинная структура и свежесть.","aroma":"Красная вишня, клубника, специи, земля и тонкие древесные оттенки.","color":"Рубиновый.","pairing":"Утка, телятина, говядина, грибы, блюда с трюфелем.","description":"Gevrey-Chambertin 2022 Aurélien Verdet — 100% Pinot Noir village-категории с Côte de Nuits. Gevrey-Chambertin традиционно считается одной из более структурных коммун Pinot Noir: в сравнении с Volnay или Chambolle здесь чаще встречаются тёмная вишня, лесная ягода, земля, специи и более заметный танин. Винтаж 2022 был зрелым, поэтому фрукт щедрый, но хорошая кислотность сохраняет бургундскую прозрачность. Verdet работает органически и избегает чрезмерной экстракции; дуб используется как инструмент созревания, а не основной аромат. Крепость около 13%.\n\nИерархия происхождения выглядит так: Bourgogne Pinot Noir — региональный уровень; Gevrey-Chambertin — village с виноградом из территории конкретной коммуны; далее идут Premier Cru и Grand Cru. Уже переход на village означает более точное происхождение и обычно большую структуру и сложность. По сравнению с региональным Bourgogne Pinot Noir это вино более структурное, землистое и рассчитанное на выдержку.","producer_description":"Aurélien Verdet — бургундский винодел из Côte de Nuits, выросший в семье, одной из ранних сторонниц органического земледелия в регионе. Он работает с собственными и контролируемыми участками в нескольких аппелласьонах Côte de Nuits и продолжает философию органической работы с почвой.\n\nВина обычно делаются с упором на чистый фрукт, умеренную экстракцию и прозрачность terroir; доля нового дуба сдержанная. Производитель менее «глянцево знаменит», чем крупнейшие домены Gevrey, но высоко ценится любителями ремесленной Бургундии. Verdet — пример того, как органическая философия и аккуратная винификация могут давать Gevrey без избыточной тяжести, сохраняя характерную структуру коммуны.","price":36800,"glass_price":"","id":"2022-gevrey-chambertin-aurélien-verdet-domaine-aurélien-verdet","image":"","price_label":"36 800 ₽","glass_price_label":""},{"sheet":"Красное","row":21,"year":"2021","title":"Cabernet Sauvignon “Artemis”","producer":"Stag's Leap Wine Cellars","category":"Красное сухое, тихое","region":"США, California, Napa Valley","country":"США","abv":"14.8%","volume":"750 мл","grapes":"98% Cabernet Sauvignon, 1% Cabernet Franc, 0.5% Malbec, 0.5% Merlot","taste":"Полнотелое, богатое и кремовое на входе; свежая середина, тёмные ягоды, шоколад и специи, интегрированные плюшевые танины.","aroma":"Boysenberry, слива, чёрная смородина, шоколад и выпечные специи.","color":"Глубокий рубиново-пурпурный.","pairing":"Стейк tri-tip, тушёные короткие рёбра, паста с лесными грибами и prosciutto.","description":"Artemis Cabernet Sauvignon 2021 — Napa Valley Cabernet от Stag's Leap Wine Cellars. Официальный состав: 98% Cabernet Sauvignon, 1% Cabernet Franc, 0,5% Malbec и 0,5% Merlot. Вино собирают из нескольких высококачественных участков Napa Valley, чтобы получить региональный портрет, а не single-vineyard. Выдержка около 15 месяцев проходит во французском дубе: примерно треть новых бочек и две трети ранее использованных. Новый дуб даёт кедр, ваниль и специи, а большая доля старых бочек сохраняет чёрную смородину, ежевику и графит. Крепость около 14,8%.\n\nArtemis — пример современного премиального Cabernet: концентрированный фрукт + структурный танин + интегрированный дуб. Artemis — региональный Napa Valley Cabernet дома, а не single-vineyard кюве; он отражает узнаваемый стиль Stag's Leap Wine Cellars. Перед подачей молодому винтажу полезен воздух; гастрономически подходят стейк, ягнёнок, говядина и выдержанные сыры.","producer_description":"Stag's Leap Wine Cellars — культовое хозяйство Napa Valley, основанное Warren Winiarski в 1970 году. Мировая известность пришла после «Judgment of Paris» 1976 года, когда Cabernet Sauvignon Stag's Leap Wine Cellars 1973 занял первое место среди красных, обойдя знаменитые Bordeaux; событие стало символом международного признания калифорнийского вина.\n\nХозяйство особенно связано со Stags Leap District и Cabernet Sauvignon, хотя Artemis собирается шире по Napa Valley. Стиль дома часто описывают как сочетание силы и шелковистой текстуры. Artemis — не то историческое вино-победитель, но оно несёт философию производителя и даёт доступ к узнаваемому стилю Napa Cabernet.","price":38200,"glass_price":"","id":"2021-cabernet-sauvignon-artemis-stag-s-leap-wine-cellars","image":"","price_label":"38 200 ₽","glass_price_label":""}]);
window.WINES=(window.WINES||[]).concat([{"sheet":"Красное","row":22,"year":"2020","title":"50&50","producer":"Capannelle & Avignonesi","category":"Красное сухое, тихое; Toscana IGT","region":"Италия, Тоскана","country":"Италия","abv":"13.5%","volume":"750 мл","grapes":"50% Sangiovese, 50% Merlot","taste":"Широкое, элегантное и округлое; сладковатые зрелые танины, чёрная вишня и ягоды, бальзамические оттенки мяты и тимьяна, долгий финиш.","aroma":"Красные ягоды, чёрная смородина, чёрная вишня, черника, подлесок, ваниль, корица.","color":"Глубокий тёмно-рубиновый с пурпурными оттенками.","pairing":"Стейк, дичь, тушёная говядина, ягнёнок, выдержанные сыры.","description":"50&50 2020 — совместное Toscana IGT от Capannelle и Avignonesi: ровно 50% Sangiovese и 50% Merlot. Идея появилась в 1988 году после дружеского сравнения вин двух хозяйств. Merlot и Sangiovese винифицируют и выдерживают раздельно, потому что они требуют разного срока сбора и по-разному реагируют на экстракцию и дуб. Merlot добавляет сливово-черничную округлость и мягкость танина, Sangiovese — вишню, кислотность, травы и тосканскую структуру.\n\nКомпоненты выдерживаются отдельно, после чего формируется финальный равный купаж. Получается не «супертосканец только из международных сортов», а диалог местного Sangiovese и мягкого Merlot: чёрная вишня, смородина, черника, подлесок, ваниль, корица, мята/тимьян, широкий вкус и шелковый танин. Крепость около 13,5%. Ключ — само происхождение проекта: два производителя, два сорта, один равный купаж. Название 50&50 буквально отражает равные доли Sangiovese и Merlot.","producer_description":"50&50 создают два тосканских хозяйства — Capannelle из Chianti и Avignonesi из Montepulciano. Проект возник не как отдельный новый дом, а как совместное вино друзей-владельцев: Sangiovese Capannelle и Merlot Avignonesi смешали в равных долях; первый релиз датируется 1988 годом.\n\nAvignonesi сегодня известна крупным органическим/биодинамическим хозяйством в районе Montepulciano, а Capannelle — небольшим estate в Gaiole in Chianti с акцентом на высококачественные тосканские вина. Кюве создаётся совместно двумя хозяйствами и объединяет два terroir и две винодельческие школы. 50&50 — хороший пример того, как Toscana IGT позволяет свободнее работать с сортами и создавать культовое вино за пределами традиционных DOCG-схем.","price":47500,"glass_price":"","id":"2020-50-50-capannelle-avignonesi","image":"","price_label":"47 500 ₽","glass_price_label":""},{"sheet":"Красное","row":23,"year":"2022","title":"Tignanello Antinori","producer":"Marchesi Antinori","category":"Красное сухое, тихое; Toscana IGT","region":"Италия, Тоскана, Chianti Classico","country":"Италия","abv":"н/д — сверить по бутылке","volume":"750 мл","grapes":"Преимущественно Sangiovese с Cabernet Sauvignon и Cabernet Franc","taste":"Плотное, но очень свежее и собранное; вишня, гранат, savoury-структура, мягкие интегрированные танины и очень длинный финиш.","aroma":"Вишня, спелая кислая вишня, гранат, фиалка, бальзамические тона, ваниль и сладкие пряности.","color":"Интенсивный рубиновый с фиолетовыми отблесками.","pairing":"Говядина, ягнёнок, дичь, паста с насыщенным рагу, зрелые сыры.","description":"Tignanello 2022 — одно из самых известных вин Antinori и ключевой символ категории «Super Tuscan». Основа купажа — Sangiovese с Cabernet Sauvignon и Cabernet Franc. Виноград происходит с одноимённого поместья Tignanello в сердце Chianti Classico, но вино маркируется Toscana IGT, потому что исторически его концепция выходила за рамки тогдашних правил аппелласьона. Каждый сорт и участок ферментируют отдельно с внимательным контролем экстракции и температуры; после малолактики компоненты созревают в небольших дубовых бочках, преимущественно французских и венгерских, затем формируется финальный купаж и следует бутылочная выдержка.\n\nСтиль 2022 — вишня и чёрная ягода, фиалка, травы, табак, графит, специи, плотный, но тонкий танин и яркая кислотность Sangiovese. Super Tuscan — не официальная категория, а историко-стилистический термин. Tignanello исторически относится к винам, изменившим представление о современной Тоскане.","producer_description":"Marchesi Antinori — одна из старейших винодельческих семей Италии: семья занимается вином с XIV века и сегодня управляет поместьями в Тоскане, Умбрии и других регионах. Tignanello связано с революцией тосканского виноделия второй половины XX века: Antinori отказались от обязательного для старых правил белого компонента, использовали Sangiovese с Cabernet и баррики, фактически помогая создать современную категорию Super Tuscan.\n\nВиноградник Tignanello находится в поместье Tenuta Tignanello между долинами Greve и Pesa. «Super Tuscan» — не официальная аппелласьонная категория, а исторический термин для амбициозных вин, которые в своё время сознательно выходили за рамки правил. Tignanello — один из ключевых примеров, объясняющих, почему Toscana IGT может быть дороже и престижнее многих DOCG.","price":53000,"glass_price":"","id":"2022-tignanello-antinori-marchesi-antinori","image":"","price_label":"53 000 ₽","glass_price_label":""},{"sheet":"Красное","row":25,"year":"2022","title":"Chianti Classico","producer":"Querciabella","category":"Красное сухое, тихое; Chianti Classico DOCG","region":"Италия, Тоскана, Chianti Classico","country":"Италия","abv":"14% — сверить по бутылке 375 мл","volume":"375 мл","grapes":"100% Sangiovese","taste":"Свежий и энергичный; тёмные ягоды и слива, яркая кислотность, уверенные танины и солоновато-землистый характер.","aroma":"Цветы, тёмные ягоды, земля, цитрусовая цедра и чайные оттенки.","color":"Молодой яркий рубиновый.","pairing":"Паста с томатным соусом, bistecca, свинина, пекорино.","description":"Querciabella Chianti Classico 2022 — 100% Sangiovese, органическое и биодинамическое вино. Виноград поступает с участков Greve in Chianti, Lamole и Radda, расположенных примерно на 350–550 м с разными экспозициями. Почвы разнообразны: galestro, мергелистые сланцы, песчаники и глина. Урожай собирают вручную в маленькие ящики; отдельные участки микровинифицируют раздельно в стали, мацерация длится примерно 12 дней, после чего партии смешивают. Выдержка — около 12–14 месяцев во французских barrique и tonneaux, доля нового дерева небольшая, затем следует бутылочная выдержка.\n\nКрепость около 14%. Это точный пример современного Chianti Classico: вишня, фиалка, подлесок, табак и кожа, яркая кислотность и тонкий танин; дуб поддерживает, а не доминирует. Формат 375 мл технологически соответствует тому же вину; маркировка конкретной партии может отличаться. По сравнению с Rocca di Montegrossi это другое выражение Chianti Classico: хозяйства различаются философией и подходом к работе с дубом.","producer_description":"Querciabella основана в 1974 году в Greve in Chianti и стала одним из пионеров органического и биодинамического подхода в Тоскане. Хозяйство постепенно перевело виноградники на органику, а затем на биодинамические методы; сегодня оно известно также принципиальной vegan-философией производства.\n\nВиноградники распределены по нескольким коммунам Chianti Classico и в Maremma, что позволяет выпускать как классический Sangiovese, так и Batàr, Camartina, Palafreno и Mongrana. В работе большое внимание уделяется biodiversity, здоровью почвы и отдельной микровинификации участков. У Querciabella экологичная философия сочетается с точной, технически дисциплинированной работой и классической структурой Chianti Classico.","price":"","glass_price":"","id":"2022-chianti-classico-querciabella","image":"","price_label":"","glass_price_label":""},{"sheet":"Красное","row":26,"year":"2020","title":"Barolo Tortoniano","producer":"Michele Chiarlo","category":"Красное сухое, тихое; Barolo DOCG","region":"Италия, Piemonte, Barolo","country":"Италия","abv":"около 14% — сверить по бутылке 375 мл","volume":"375 мл","grapes":"100% Nebbiolo","taste":"Широкое и структурное, но уже гармоничное; шелковистые танины, элегантность и продолжительный финиш.","aroma":"Лепестки роз, можжевеловые ягоды и тонкие специи.","color":"Гранатовый с яркими бликами.","pairing":"Феттучини с porcini, мясо, тушённое в Barolo, голубь, хорошо выдержанные сыры.","description":"Barolo Tortoniano 2020 Michele Chiarlo — 100% Nebbiolo и классический Barolo DOCG. После сбора виноград ферментирует в стали; мацерация на кожице длится около двух с лишним недель с мягкой системой смачивания шапки, чтобы извлечь цвет и танин без грубости. Затем вино проходит обязательное длительное созревание: значительная часть срока — в средних и крупных дубовых ёмкостях, после чего следует бутылочная выдержка. Крупный дуб не должен давать яркую ваниль, его роль — смягчать Nebbiolo через медленную оксигенацию.\n\nВинтаж 2020 находится около 14% об. Профиль — роза, красная вишня, сушёные травы, можжевельник, специи, лакрица, строгая кислотность и танин. Производитель официально выпускает Tortoniano в 375 мл, поэтому формат вашей позиции логичен. Tortoniano — классическое выражение Barolo из Nebbiolo; при одном сорте и аппелласьоне его стиль отличается от Fenocchio за счёт подхода хозяйства и техники.","producer_description":"Michele Chiarlo — пьемонтское семейное хозяйство, основанное Микеле Кьярло в 1956 году. Производитель работает в нескольких ключевых зонах Piemonte — Barolo, Barbaresco, Barbera d’Asti и Gavi — и владеет или обрабатывает престижные участки, включая Cerequio и Cannubi.\n\nСтиль сочетает традиционное уважение к Nebbiolo с точной современной техникой: контролируемая ферментация, мягкая экстракция и выдержка преимущественно в более крупных дубовых ёмкостях для Barolo. Хозяйство уделяет внимание устойчивому развитию. Tortoniano — не single-cru, а классический Barolo дома, созданный как понятное выражение сорта и зоны. Chiarlo — хороший ориентир между строгим традиционализмом и современной чистотой.","price":"","glass_price":"","id":"2020-barolo-tortoniano-michele-chiarlo","image":"","price_label":"","glass_price_label":""}]);
